import { makeAlign, type AlignObject } from "@kvisaz/phaser-common";
import type { ILeaderboardRow, ILeaderboardState } from "./types";
import { DialogShell } from "../dialog/DialogView/components/DialogShell";
import type { DialogButton } from "../dialog/types";
import { leaderboardConfig } from "./config";
import { LeaderboardTable } from "./LeaderboardTable/LeaderboardTable";
import { LeaderboardFailed } from "./LeaderboardFailed/LeaderboardFailed";
import { LeaderboardSpinner } from "./LeaderboardSpinner/LeaderboardSpinner";
import { dialogTitleStyle } from "../dialog/config";

interface ILeaderboardWindowProps {
  scene: Phaser.Scene;
  title: string;
  /** крестик создан вызывающим: он знает, что делать при закрытии */
  closeButton: DialogButton;
  /** уже переведённые надписи окна */
  texts: { failed: string; you: string; anonymous: string };
  /** есть — при ошибке показываем созданную им кнопку «Ещё раз»; фабрика, потому что содержимое пересоздаётся */
  createRetryButton?: () => DialogButton;
}

/**
 * Окно рейтинга. Рамка и шапка создаются один раз, высота фиксирована под maxRows строк;
 * содержимое под шапкой — пусто, пока владелец не вызовет showState, и меняется только им.
 * Props не хранит: у DialogShell уже есть приватное поле props, одноимённое поле наследника не собрать.
 */
export class LeaderboardWindow extends DialogShell {
  private readonly texts: ILeaderboardWindowProps["texts"];
  private readonly createRetryButton?: ILeaderboardWindowProps["createRetryButton"];
  /** не body: это имя занято физическим телом Phaser GameObject */
  private content?: Phaser.GameObjects.GameObject & AlignObject;

  constructor({ scene, title, closeButton, texts, createRetryButton }: ILeaderboardWindowProps) {
    const { rowHeight, rowGap, maxRows, tableTop, tableBottom } = leaderboardConfig;
    const height =
      dialogTitleStyle.height + tableTop + maxRows * (rowHeight + rowGap) - rowGap + tableBottom;

    super({ scene, title, closeButton, height });
    this.texts = texts;
    this.createRetryButton = createRetryButton;
  }

  /** Меняет содержимое под шапкой на таблицу, загрузку, ошибку или пустой текст. */
  showState(state: ILeaderboardState) {
    const { scene, bg, texts, createRetryButton } = this;
    this.content?.destroy();

    // Сначала в рамку, потом выравнивание: позиции считаются уже внутри окна.
    const content = makeContent(scene, state, texts, createRetryButton);
    this.add(content);
    placeContent(bg, content);
    if (content instanceof LeaderboardTable) content.start();
    this.content = content;
  }
}

/**
 * Видимые строки: отбор (верх и соседи игрока) уже сделал сервис, здесь только предел maxRows.
 * Игрок без места — последней строкой с rank 0: место и очки «—».
 */
function visibleRows({ rows, playerRank }: ILeaderboardState): ILeaderboardRow[] {
  const { maxRows } = leaderboardConfig;
  if (playerRank == null) return [...rows.slice(0, maxRows - 1), { rank: 0, name: "", score: 0 }];

  /** Соседи игрока остаются всегда, топ усыхает ровно настолько, чтобы влезть в maxRows. */
  const bottoms = rows.filter((row) => row.rank >= playerRank - 1);
  const tops = rows.filter((row) => row.rank < playerRank - 1).slice(0, maxRows - bottoms.length);
  return [...tops, ...bottoms];
}

/** Содержимое под шапкой: спиннер, ошибка или таблица. */
function makeContent(
  scene: Phaser.Scene,
  state: ILeaderboardState,
  texts: ILeaderboardWindowProps["texts"],
  createRetryButton: ILeaderboardWindowProps["createRetryButton"],
) {
  if (state.status === "loading") return new LeaderboardSpinner({ scene });
  if (state.status === "failed")
    return new LeaderboardFailed({ scene, text: texts.failed, retryButton: createRetryButton?.() });
  // Пустая доска — таблица из одного игрока с нулём и пустых строк.
  const isBoardEmpty = !state.rows.length;
  const rows = isBoardEmpty ? [{ rank: 1, name: "", score: 0 }] : visibleRows(state);
  const playerRank = isBoardEmpty ? 1 : state.playerRank;
  return new LeaderboardTable({
    scene,
    rows,
    playerRank,
    youText: texts.you,
    anonymousText: texts.anonymous,
  });
}

/** Ставит содержимое в рамку: таблица — сверху под шапкой, спиннер и текст — по центру области под шапкой. */
function placeContent(frame: AlignObject, content: AlignObject) {
  const titleHeight = dialogTitleStyle.height;
  makeAlign((a) => {
    if (content instanceof LeaderboardTable) {
      a.anchor(frame)
        .centerX(content)
        .topIn(content, titleHeight + leaderboardConfig.tableTop);
      return;
    }
    // Шапка не перекрывается: отступ от верха — половина свободного места под ней.
    const top =
      titleHeight + (frame.getBounds().height - titleHeight - content.getBounds().height) / 2;
    a.anchor(frame).centerX(content).topIn(content, top);
  });
}
