interface ICountUpTextProps {
  scene: Phaser.Scene;
  value: number;
  /** Сколько цифр показывать: недостающие слева заполняются нулями. */
  digits: number;
  style: Phaser.Types.GameObjects.Text.TextStyle;
  durationMs: number;
  delayMs?: number;
}

/**
 * Число с ведущими нулями, которое «набегает» от нуля до значения, как в классических анимациях выигрыша.
 * Левый край закреплён: ведущие нули выравниваются колонкой по левому краю, рост числа её не сдвигает.
 */
export class CountUpText extends Phaser.GameObjects.Text {
  private tween?: Phaser.Tweens.Tween;

  constructor(private readonly props: ICountUpTextProps) {
    super(props.scene, 0, 0, "", props.style);
    this.setText(this.format(0));
    props.scene.add.existing(this);
  }

  /** Запускает набег; при уничтожении текста твин останавливается. */
  start(): this {
    const { scene, value, durationMs, delayMs = 0 } = this.props;
    this.tween?.remove();
    this.tween = scene.tweens.addCounter({
      from: 0,
      to: value,
      duration: durationMs,
      delay: delayMs,
      ease: Phaser.Math.Easing.Sine.Out,
      onUpdate: (counter) => this.setText(this.format(Math.round(counter.getValue() ?? 0))),
    });
    return this;
  }

  destroy(fromScene?: boolean) {
    this.tween?.remove();
    this.tween = undefined;
    super.destroy(fromScene);
  }

  private format(value: number): string {
    return String(value).padStart(this.props.digits, "0");
  }
}
