import {
  CardView as CoreCardView,
  CardSuit,
  createSimpleCardData,
  scaleToSize,
  isSuitRed,
  makeAlign,
  makeView,
  type CardSide,
  type CardValue,
} from "@kvisaz/phaser-common";
import { getImageAsset } from "../../../assets";
import { uiColors, uiFonts } from "../style";
import { CardMotion3D } from "./CardMotion3D/CardMotion3D";

export const CARD_WIDTH = 154;
export const CARD_HEIGHT = 210;
export const suitAssets = {
  [CardSuit.spade]: "suitSpade",
  [CardSuit.heart]: "suitHeart",
  [CardSuit.club]: "suitClub",
  [CardSuit.diamond]: "suitDiamond",
} as const;
const figureNames = { jack: "Jack", queen: "Queen", king: "King", ace: "Ace" } as const;
const suitNames = {
  [CardSuit.spade]: "Spade",
  [CardSuit.heart]: "Heart",
  [CardSuit.club]: "Club",
  [CardSuit.diamond]: "Diamond",
} as const;
/** Ячейка атласа больше карты для резкости; 9 × 6 ячеек (1980 × 1800) влезают в предел текстуры 2048 px. */
const faceAtlasConfig = {
  cellWidth: 220,
  cellHeight: 300,
  atlasColumns: 9,
  textResolution: 2,
} as const;

export interface CardProps {
  scene: Phaser.Scene;
  id: string;
  suit: CardSuit;
  value: CardValue;
  side?: CardSide;
  t(key: string): string;
}

/** Карта Classic XL на библиотечном контракте: id, suit, value, side, flip и stackId. */
export class CardView extends CoreCardView {
  readonly id: string;
  readonly suit: CardSuit;
  readonly value: CardValue;

  private motion?: CardMotion3D;

  /** Лицо — кадр общего атласа; контракт карты и рубашка не меняются. */
  constructor({ scene, t, id, suit, value, side = "back" }: CardProps) {
    const faceTextureKey = ensureCardFaceAtlas(scene, t);
    const face = makeView(scene, (b) =>
      b.img({ textureName: faceTextureKey, frameName: getFaceFrameName(suit, value) }),
    );
    scaleToSize({ gameObject: face, width: CARD_WIDTH, height: CARD_HEIGHT });
    const back = makeView(scene, (b) => b.img(getImageAsset("cardBack")));
    super({ scene, faceImage: face, backImage: back, initSide: side, initStackId: "deck" });
    this.id = id;
    this.suit = suit;
    this.value = value;

    /** Mesh рисуется только в WebGL: на Canvas карта остаётся плоской. */
    if (scene.sys.game.renderer.type !== Phaser.WEBGL) return;

    this.motion = new CardMotion3D({
      scene,
      card: this,
      textureKey: faceTextureKey,
      frame: getFaceFrameName(suit, value),
      width: CARD_WIDTH,
      height: CARD_HEIGHT,
      hideFlatFace: () => this.faceImage.setVisible(false),
      showFlatFace: () => this.updateImages(),
    });
  }

  /** Снимает подписки движения; его Mesh уничтожается вместе с детьми контейнера. */
  override destroy(fromScene?: boolean) {
    this.motion?.destroy();
    super.destroy(fromScene);
  }

  /** Любая смена стороны завершает наклон: Mesh показывает только лицо. */
  protected override updateImages() {
    this.motion?.hideMesh();
    super.updateImages();
  }
}

/**
 * Один атлас на язык: все лица запекаются разом.
 * Boot делает это при загрузке; сторибук и смена языка — при создании первой карты.
 */
export function ensureCardFaceAtlas(scene: Phaser.Scene, t: CardProps["t"]): string {
  /** Ранг туза различается в языках и потому годится как ключ языка. */
  const key = `_cardViewFaces_${t("rank_ace")}`;
  if (scene.textures.exists(key)) return key;

  /** Подписи запоминаем сразу: t читает текущий язык, а перерисовка должна сохранить язык атласа. */
  const rankLabels = {
    jack: t("rank_jack"),
    queen: t("rank_queen"),
    king: t("rank_king"),
    ace: t("rank_ace"),
  };

  const { cellWidth, cellHeight, atlasColumns } = faceAtlasConfig;
  const deck = createSimpleCardData({ shuffle: false });
  const rows = Math.ceil(deck.length / atlasColumns);
  const atlas = scene.textures.addDynamicTexture(key, cellWidth * atlasColumns, cellHeight * rows)!;

  const getCell = (index: number) => ({
    x: (index % atlasColumns) * cellWidth,
    y: Math.floor(index / atlasColumns) * cellHeight,
  });
  deck.forEach(({ suit, value }, index) => {
    const { x, y } = getCell(index);
    atlas.add(getFaceFrameName(suit, value), 0, x, y, cellWidth, cellHeight);
  });

  /** Текст и картинки живут до конца отрисовки, поэтому удаляем их только после endDraw. */
  const drawFaces = () => {
    const faces = deck.map(({ suit, value }) =>
      buildCardFace(scene, rankLabels, suit, value).setScale(cellWidth / CARD_WIDTH),
    );
    atlas.clear();
    atlas.beginDraw();
    faces.forEach((face, index) => {
      const { x, y } = getCell(index);
      atlas.batchDraw(face, x + cellWidth / 2, y + cellHeight / 2);
    });
    atlas.endDraw();
    faces.forEach((face) => face.destroy());
  };
  drawFaces();

  /** Содержимое DynamicTexture не переживает потерю контекста WebGL: рисуем заново. */
  const { renderer } = scene.sys.game;
  if (renderer.type === Phaser.WEBGL) renderer.on(Phaser.Renderer.Events.RESTORE_WEBGL, drawFaces);

  return key;
}

/** Имя кадра лица в атласе. */
function getFaceFrameName(suit: CardSuit, value: CardValue): string {
  return `${suit}_${value}`;
}

/** Собирает лицо с мастью или фигурой J/Q/K/A: временный объект для запекания в атлас. */
function buildCardFace(
  scene: Phaser.Scene,
  rankLabels: Record<keyof typeof figureNames, string>,
  suit: CardSuit,
  value: CardValue,
) {
  return makeView(scene, (b) => {
    const bg = b.img(getImageAsset("cardFace"));
    const style = {
      fontFamily: uiFonts.notoSerifBold.fontFamily,
      fontSize: 27,
      color: isSuitRed(suit) ? uiColors.red : uiColors.ink,
      resolution: faceAtlasConfig.textResolution,
    };
    const label = typeof value === "string" ? rankLabels[value] : String(value);
    const upper = b.text({ text: label, style });
    const lower = b.text({ text: label, style });
    const small = b.img(getImageAsset(suitAssets[suit])).setDisplaySize(22, 24);
    const figure = typeof value === "string";
    const center = b.img(
      getImageAsset(figure ? `card${figureNames[value]}${suitNames[suit]}` : suitAssets[suit]),
    );
    // Целевая область не зависит от разрешения PNG; пропорции сохраняются.
    scaleToSize({ gameObject: center, width: figure ? 117 : 60, height: figure ? 130 : 65 });
    makeAlign((a) => {
      a.anchor(bg).leftIn(upper, 16).topIn(upper, 7);
      a.rightIn(lower, -16).bottomIn(lower, -10);
      a.anchor(upper).rightTo(small, 5).centerY(small);
      a.anchor(bg).center(center);
    });
    return b.con([bg, upper, lower, small, center]);
  });
}
