import { makeAlign, makeView, row } from "@kvisaz/phaser-common";
import { getImageAsset } from "../../../../../assets";
import { DialogTitle } from "./DialogTitle";
import type { DialogButton } from "../../types";
import { dialogShellStyle } from "../../config";

interface IDialogShellProps {
  scene: Phaser.Scene;
  title: string;
  /** крестик в шапке, уже созданный вызывающим; без него крестика нет */
  closeButton?: DialogButton;
  /** кнопки внизу, уже созданные вызывающим: идут одним рядом по центру */
  buttons?: DialogButton[];
  /** фиксированная высота на всё время жизни окна; по умолчанию 740, ширина у всех окон одна */
  height?: number;
}

/**
 * Окно Classic XL: рамка, шапка с крестиком и кнопки внизу. Содержимое вызывающий добавляет через add
 * и ставит его относительно frame. Высота задаётся один раз при создании.
 */
export class DialogShell extends Phaser.GameObjects.Container {
  /** рамка окна: относительно неё ставят содержимое */
  readonly bg: Phaser.GameObjects.NineSlice;

  constructor(private props: IDialogShellProps) {
    super(props.scene, 0, 0);
    const { scene, title, closeButton, buttons = [], height = dialogShellStyle.height } = props;
    const { width, nineSlicePadding } = dialogShellStyle;

    this.bg = makeView(scene, (b) =>
      b.nine({
        ...getImageAsset("windowBackground"),
        width,
        height,
        padding: nineSlicePadding,
      }),
    );
    const titleView = new DialogTitle({ scene, title, width, closeButton });
    makeAlign((a) => a.anchor(this.bg).leftIn(titleView).topIn(titleView));

    this.placeButtons();
    this.add([this.bg, titleView, ...buttons]);
  }

  /** Кнопки одним рядом: по центру рамки, у нижнего края. */
  private placeButtons() {
    const { buttons = [] } = this.props;
    if (buttons.length === 0) return;
    const { bg } = this;
    const { buttonsBottom, buttonsGap } = dialogShellStyle;
    const buttonRow = row(buttons, { nextOffsetX: buttonsGap });
    makeAlign((a) => a.anchor(bg).centerX(buttonRow).bottomIn(buttonRow, buttonsBottom));
  }
}
