import { arrayAlign, makeAlign } from "@kvisaz/phaser-common";
import type { SolitaireLayout } from "../types";

/**
 * Косынка: семь колонок по центру, над ними колода и сброс слева, четыре базы справа.
 * Колода выровнена по левому краю первой колонки, базы — по правому краю последней.
 * Шаг и верх карт — из конфига: макет меряет видимую карту 144×200, а место 154×210 шире на тень.
 */
export const layoutKlondike: SolitaireLayout = (scene, { tables, bases, stock, waste }, config) => {
  /** Сдвиг центра поля по X: макет центрирован без сдвига, px. */
  const centerXOffset = 0;
  const { cardsTopY, placeGap } = config;
  const tableTopY = cardsTopY + stock!.getBounds().height + placeGap;
  makeAlign((a) => {
    a.row(tables, placeGap);
    const tableBounds = arrayAlign.alignObject(tables);
    a.anchorSceneScreen(scene).centerX(tableBounds, centerXOffset).topIn(tableBounds, tableTopY);
    a.row([stock!, waste!], placeGap);
    a.row(bases, placeGap);
    const deck = arrayAlign.alignObject([stock!, waste!]);
    const baseRow = arrayAlign.alignObject(bases);
    a.anchor(tableBounds).leftIn(deck).rightIn(baseRow);
    a.anchorSceneScreen(scene).topIn(deck, cardsTopY).topIn(baseRow, cardsTopY);
  });
};
