import { arrayAlign, makeAlign } from "@kvisaz/phaser-common";
import type { SolitaireLayout } from "../types";

/**
 * Юкон: семь колонок по центру, над ними четыре базы по центру стола. Шаг и верх карт — из конфига.
 */
export const layoutYukon: SolitaireLayout = (scene, { tables, bases }, config) => {
  /** Сдвиг центра поля по X: центр стола совпадает с центром экрана, px. */
  const centerXOffset = 0;
  const { cardsTopY, placeGap } = config;
  const tableTopY = cardsTopY + bases[0].getBounds().height + placeGap;
  makeAlign((a) => {
    a.row(tables, placeGap);
    const tableBounds = arrayAlign.alignObject(tables);
    a.anchorSceneScreen(scene).centerX(tableBounds, centerXOffset).topIn(tableBounds, tableTopY);
    a.row(bases, placeGap);
    const baseRow = arrayAlign.alignObject(bases);
    a.anchor(tableBounds).centerX(baseRow);
    a.anchorSceneScreen(scene).topIn(baseRow, cardsTopY);
  });
};
