import { makeAlign, makeView, scaleToSize } from "@kvisaz/phaser-common";
import { getImageAsset } from "../../../../assets";
import { CountUpText } from "../../CountUpText/CountUpText";
import { uiFonts, uiTextStyle } from "../../style";
import { leaderboardConfig } from "../config";

interface ILeaderboardRowProps {
  scene: Phaser.Scene;
  /** место; 0 — результата нет: вместо места и очков «—» */
  rank: number;
  name: string;
  score: number;
  /** сколько цифр у очков: недостающие слева — нули */
  digits: number;
  /** строка игрока: золотой фон, сердечко у имени, имя жирнее */
  isPlayer: boolean;
  /** заполнитель таблицы: место и имя как переданы, очков нет — «—» */
  isEmpty?: boolean;
}

/** Строка рейтинга на ассетах игры: место, имя и очки; очки набегают при start(). */
export class LeaderboardRow extends Phaser.GameObjects.Container {
  private readonly counter?: CountUpText;

  constructor(private props: ILeaderboardRowProps) {
    super(props.scene, 0, 0);
    const { scene, rank, name, score, digits, isPlayer, isEmpty } = this.props;
    const {
      rowWidth,
      rowHeight,
      rowColor,
      playerRowColor,
      fontSize,
      heartWidth,
      heartHeight,
      heartGap,
      countUpMs,
    } = leaderboardConfig;
    const style = uiTextStyle(fontSize);
    const hasScore = rank > 0 && !isEmpty;
    this.counter = hasScore
      ? new CountUpText({ scene, value: score, digits, style, durationMs: countUpMs })
      : undefined;

    makeView(scene, (b) => {
      const bg = b.rect({
        width: rowWidth,
        height: rowHeight,
        color: isPlayer ? playerRowColor : rowColor,
      });
      const rankText = b.text({ text: rank > 0 ? `${rank}.` : "—", style });
      const nameText = b.text({
        text: name,
        style: isPlayer ? { ...style, fontFamily: uiFonts.interSemibold.fontFamily } : style,
      });
      const value = this.counter ?? b.text({ text: "—", style });
      const heart = isPlayer ? b.img(getImageAsset("suitHeart")) : undefined;
      // Вписываем с сохранением пропорций: спрайт масти не сплющится.
      if (heart) scaleToSize({ gameObject: heart, width: heartWidth, height: heartHeight });

      makeAlign((a) => {
        a.anchor(bg).leftIn(rankText, 24).centerY(rankText).leftIn(nameText, 140).centerY(nameText);
        a.rightIn(value, -24).centerY(value);
        if (heart) a.anchor(nameText).rightTo(heart, heartGap).centerY(heart);
      });
      this.add([bg, rankText, nameText, value, ...(heart ? [heart] : [])]);
      return bg;
    });
  }

  /** Запускает набег очков; у строки без результата ничего не делает. */
  start() {
    this.counter?.start();
  }
}
