import type { ScoreCardObject, ScoreStacks } from "../types";

/**
 * Стопки по stackId, карты снизу вверх — по порядку отрисовки на сцене.
 * Партии стопки наружу не отдают; движок кладёт каждую карту стопки поверх предыдущей.
 */
export function collectStacks(cards: readonly ScoreCardObject[]): ScoreStacks {
  const stacks = new Map<string, ScoreCardObject[]>();
  const order = (card: ScoreCardObject) => card.scene.children.getIndex(card);
  [...cards]
    .sort((a, b) => order(a) - order(b))
    .forEach((card) => {
      stacks.set(card.stackId, [...(stacks.get(card.stackId) ?? []), card]);
    });
  return stacks;
}
