import {
  HtmlBackground,
  makeButton,
  makeView,
  SafeEventsAdapter,
  UnSubManager,
  arrayAlign,
  makeAlign,
} from "@kvisaz/phaser-common";
import { autoAssetsConfig } from "../../../autoAssetsConfig";
import { getImageAsset } from "../../../assets";
import type { IMenuEvents } from "../events";
import { solitaireIds, type SolitaireId } from "../../../scenes";
import { variants } from "../../Solitaire/solitaires/variants";
import { iconButton, textButton } from "../../shared/buttons";
import { uiColors, uiFonts } from "../../shared/style";
import { Dialogs } from "../../shared/dialog/Dialogs";
import { LeaderboardWindow } from "../../shared/LeaderboardView/LeaderboardWindow";
import type { ILeaderboardState } from "../../shared/LeaderboardView/types";

const layout = { buttonWidth: 680, buttonHeight: 98, buttonGap: 18, slice: 16, trophySize: 64 };

interface IMenuViewProps {
  scene: Phaser.Scene;
  events: Phaser.Events.EventEmitter;
  t(key: string): string;
  isWinAnimationAllowed(): boolean;
  onWinAnimationAllowedChange(value: boolean): void;
  isTableWithPlayer(board: SolitaireId): boolean;
  loadLeaderboard(board: SolitaireId): Promise<ILeaderboardState>;
}

/** Стартовый экран: пять игр и отдельный стенд проверки стартера. */
export class MenuView {
  private readonly unSubs = new UnSubManager();

  /** Собирает Classic XL из PNG и текста; интерактивность подключает makeButton. */
  constructor(private readonly props: IMenuViewProps) {
    const { scene, t, isWinAnimationAllowed, onWinAnimationAllowedChange } = props;

    /** Меню использует свой контракт поверх общего источника событий. */
    const events = new SafeEventsAdapter<IMenuEvents>(props.events);
    this.unSubs.addUnSub(() => events.unSubscribeAll());

    this.unSubs.addUnSub(new HtmlBackground({ url: autoAssetsConfig.images.backgroundCloth.url }));
    const buttons = solitaireIds.map((id) => {
      const button = makeView(scene, (b) => {
        const bg = b.nine({
          ...getImageAsset("buttonDefault"),
          width: layout.buttonWidth,
          height: layout.buttonHeight,
          padding: layout.slice,
        });
        const icon = b.img(getImageAsset(variants[id].config.menuIcon)).setDisplaySize(32, 35);
        const label = b.text({
          text: t(id),
          style: {
            fontFamily: uiFonts.interSemibold.fontFamily,
            fontSize: "38px",
            color: uiColors.ink,
          },
        });
        makeAlign((a) => {
          a.anchor(bg).leftIn(icon, 28).centerY(icon);
          a.leftIn(label, 86).centerY(label);
        });
        return b.con([bg, icon, label]);
      });
      makeButton({
        obj: button,
        onClick: () => {
          events.emit("uiClick");
          events.emit("requestGameScreen", { gameId: id });
        },
        onHover: () => events.emit("uiHover"),
        onOut: () => events.emit("uiOut"),
      });
      return button;
    });
    const dialogs = new Dialogs({
      scene,
      events: props.events,
      t,
      isWinAnimationAllowed,
      onWinAnimationAllowedChange,
    });
    const trophies = solitaireIds.map((id) =>
      makeButton({
        obj: makeView(scene, (b) => {
          const bg = b.nine({
            ...getImageAsset("buttonDefault"),
            width: layout.buttonHeight,
            height: layout.buttonHeight,
            padding: layout.slice,
          });
          const trophy = b
            .img(getImageAsset("dialogWin"))
            .setDisplaySize(layout.trophySize, layout.trophySize);
          makeAlign((a) => a.anchor(bg).center(trophy));
          return b.con([bg, trophy]);
        }),
        onClick: () => {
          events.emit("uiClick");
          this.openLeaderboard(dialogs, id);
        },
        onHover: () => events.emit("uiHover"),
        onOut: () => events.emit("uiOut"),
      }).setVisible(props.isTableWithPlayer(id)),
    );
    const settings = iconButton({
      scene,
      events: props.events,
      name: "settings",
      onClick: () => dialogs.open("settings"),
    });
    this.unSubs.addUnSub([dialogs, settings, ...buttons, ...trophies]);
    makeView(scene, (b) => {
      const hero = b.img(getImageAsset("hero02")).setDisplaySize(660, 660);
      const title = b.text({
        text: t("title"),
        style: {
          fontFamily: uiFonts.notoSerifBold.fontFamily,
          fontSize: "88px",
          color: uiColors.cream,
        },
      });
      const subtitle = b.text({
        text: t("menu_subtitle"),
        style: { fontFamily: uiFonts.interRegular.fontFamily, fontSize: "32px", color: "#d6e1cf" },
      });
      makeAlign((a) => {
        a.column(buttons, layout.buttonGap);
        buttons.forEach((button, i) =>
          a.anchor(button).rightTo(trophies[i], layout.buttonGap).centerY(trophies[i]),
        );
      });
      const choices = arrayAlign.alignObject([...buttons, ...trophies]);
      makeAlign((a) => {
        a.anchorSceneScreen(scene);
        a.leftIn(title, 120).topIn(title, 146);
        a.leftIn(subtitle, 126).topIn(subtitle, 279);
        a.leftIn(hero, 116).topIn(hero, 344);
        a.rightIn(choices, -130).topIn(choices, 240);
        a.anchorSceneScreen(scene);
        a.rightIn(settings, -48).topIn(settings, 12);
      });
      this.unSubs.addUnSub([hero, title, subtitle]);
      return hero;
    });
  }

  /** Готовый Dialogs управляет окном; меню связывает таблицу с загрузкой и повтором. */
  private openLeaderboard(dialogs: Dialogs, board: SolitaireId): void {
    const { events, t, loadLeaderboard } = this.props;
    dialogs.show((scene, close) => {
      const window = new LeaderboardWindow({
        scene,
        title: `${t("leaderboard_title")} · ${t(board)}`,
        closeButton: iconButton({ scene, events, name: "close", onClick: () => close() }),
        texts: {
          failed: t("leaderboard_failed"),
          you: t("leaderboard_you"),
          anonymous: t("leaderboard_anonymous"),
        },
        createRetryButton: () =>
          textButton({
            scene,
            events,
            text: t("leaderboard_retry"),
            onClick: () => {
              void refresh();
            },
            variant: "primary",
            width: 500,
          }),
      });
      /** Ответ не обновляет окно, если его уже закрыли. */
      const refresh = async () => {
        window.showState({ status: "loading", rows: [] });
        try {
          const state = await loadLeaderboard(board);
          if (window.scene) window.showState(state);
        } catch {
          if (window.scene) window.showState({ status: "failed", rows: [] });
        }
      };
      void refresh();
      return window;
    });
  }

  /** Удаляет меню при завершении его сцены. */
  destroy(): void {
    this.unSubs.destroy();
  }
}
