import { makeButton, makeView, makeAlign, SafeEventsAdapter } from "@kvisaz/phaser-common";
import type { IDemoEvents } from "../events";
import { uiColors, uiTextStyle } from "../../../shared/style";

interface IScreenButtonProps {
  scene: Phaser.Scene;
  events: Phaser.Events.EventEmitter;
}

/** Общая кнопка экранов; звуковые события обрабатывает постоянный сервис. */
export function demoScreenButton(context: IScreenButtonProps, text: string, run: () => void) {
  const { scene } = context;
  const events = new SafeEventsAdapter<IDemoEvents>(context.events);
  const button = makeView(scene, (b) => {
    const bg = b.rect({ width: 270, height: 64, color: uiColors.gold });
    const label = b.text({ text, style: uiTextStyle(26, uiColors.ink) });
    makeAlign((a) => a.anchor(bg).center(label));
    return b.con([bg, label]);
  });
  return makeButton({
    obj: button,
    onClick: () => {
      events.emit("uiClick");
      run();
    },
    onHover: () => events.emit("uiHover"),
    onOut: () => events.emit("uiOut"),
  });
}
