import { type AlignObject, Anima, makeAlign } from "@kvisaz/phaser-common";
import type { SolitaireId } from "../../../configs/config.games";
import { textButton } from "../buttons";

interface IMakeAutoCollectButtonProps {
  scene: Phaser.Scene;
  events: Phaser.Events.EventEmitter;
  text: string;

  /** Что сделать при клике; кнопка к этому моменту уже уничтожена. */
  onClick(): void;
}

/**
 * Компактная кнопка «Собрать» без места и анимации: размер меньше обычного,
 * между рядом баз и колонками зазор 40 px, а не 520×112 с шрифтом 40.
 * Место задаёт layoutAutoCollectButton, анимацию — startAutoCollectCta. Клик уничтожает кнопку.
 */
export function makeAutoCollectButton({
  scene,
  events,
  text,
  onClick,
}: IMakeAutoCollectButtonProps) {
  const button = textButton({
    scene,
    events,
    text,
    variant: "primary",
    width: 160,
    height: 42,
    fontSize: 22,
    onClick: () => {
      button.destroy();
      onClick();
    },
  });

  return button;
}

interface ILayoutAutoCollectButtonProps {
  button: AlignObject;
  /** Ряд баз: готовый ArrayAlignObject или одно место — подойдёт любой AlignObject. */
  bases: AlignObject;
  /** Игра: место общее для всех, но по типу игры его можно будет поправить. */
  gameId: SolitaireId;
}

export function layoutAutoCollectButton({ button, bases, gameId }: ILayoutAutoCollectButtonProps) {
  makeAlign((a) => {
    switch (gameId) {
      case "spider": {
        a.anchor(bases).centerY(button, 18).leftTo(button, -13);
        break;
      }

      case "fortyThieves": {
        a.anchor(bases).centerY(button, 18).leftTo(button, -8);
        break;
      }

      default: {
        a.anchor(bases).centerY(button, 18).leftTo(button, -34);
      }
    }
  });
}

/**
 * CTA из phaser-common, как у AutoCompleteButton старой Косынки: 22 подпрыгивания по 0.9 с и свечение.
 * Вызывать после layoutAutoCollectButton: подпрыгивание считается от текущей высоты кнопки.
 * Твины гасятся при уничтожении кнопки, кто бы её ни убрал.
 */
export function startAutoCollectCta(button: Phaser.GameObjects.Container) {
  Anima.popItem({
    target: button,
    repeat: 22,
    duration: 22 * 900,
    scaleAmount: 1,
    upDistance: -18,
  });
  button.postFX?.addGlow();
  button.once("destroy", () => button.scene?.tweens.killTweensOf(button));
}
