import {
  CindUi,
  cssColorToInt,
  fitToSize,
  makeAlign,
  makeButton,
  makeView,
  SafeEventsAdapter,
} from "@kvisaz/phaser-common";
import { getImageAsset } from "../../assets";
import type { IUiEvents } from "./events";
import { fadeSmooth } from "./fadeSmooth/fadeSmooth";
import { uiColors, uiFonts, uiTextStyle } from "./style";

export const iconAssets = {
  home: "iconHome",
  undo: "iconUndo",
  hint: "iconHint",
  newGame: "iconNewGame",
  magic: "iconMagicCard",
  settings: "iconSettings",
  close: "iconClose",
} as const;
export type IconName = keyof typeof iconAssets;

interface IIconButtonProps {
  scene: Phaser.Scene;
  events: Phaser.Events.EventEmitter;
  name: IconName;
  onClick: () => void;
  /** Сторона иконки в пикселях, по умолчанию 128. */
  size?: number;
}

/**
 * Все кнопки — Image/Container через makeView и makeButton: клик, hover и disabled
 * приходят из библиотеки, своих обработчиков указателя нет.
 * Disabled-вид — плавный tint через fadeSmooth,
 * чтобы кнопка не мигала при смене enabled во время хода.
 */
export function iconButton({
  scene,
  events: emitter,
  name,
  onClick,
  size = 128,
}: IIconButtonProps) {
  const events = new SafeEventsAdapter<IUiEvents>(emitter);
  const image = makeView(scene, (b) => b.img(getImageAsset(iconAssets[name])));
  fitToSize({ gameObject: image, width: size, height: size });
  return makeButton({
    obj: image,
    onClick: () => {
      events.emit("uiClick");
      onClick();
    },
    onHover: () => events.emit("uiHover"),
    onOut: () => events.emit("uiOut"),
    onEnabledChange: (obj, enabled) =>
      fadeSmooth({ obj, faded: !enabled, tint: cssColorToInt("#939090"), delayToFade: 250 }),
  }).setName(name);
}

interface ITextButtonProps {
  scene: Phaser.Scene;
  events: Phaser.Events.EventEmitter;
  text: string;
  onClick: () => void;
  /** Фон дизайна: default, primary (по умолчанию) или secondary. */
  variant?: "default" | "primary" | "secondary";
  /** Ширина кнопки, по умолчанию 520. */
  width?: number;
  /** Высота кнопки, по умолчанию 112. */
  height?: number;
  /** withSound=false — без звука клика и наведения. */
  withSound?: boolean;
  /** Размер шрифта подписи, по умолчанию 40. */
  fontSize?: number;
}

/** Текстовая кнопка с одним из трёх NineSlice-фонов дизайна. */
export function textButton({
  scene,
  events: emitter,
  text,
  onClick,
  variant = "primary",
  width = 520,
  height = 112,
  withSound = true,
  fontSize = 40,
}: ITextButtonProps) {
  const events = new SafeEventsAdapter<IUiEvents>(emitter);
  const assets = {
    default: "buttonDefault",
    primary: "buttonPrimary",
    secondary: "buttonSecondary",
  } as const;
  const button = makeView(scene, (b) => {
    const bg = b.nine({ ...getImageAsset(assets[variant]), width, height, padding: 16 });
    const label = b.text({
      text,
      style: {
        fontFamily: uiFonts.interSemibold.fontFamily,
        fontSize,
        color: variant === "primary" ? uiColors.cream : uiColors.ink,
      },
    });
    makeAlign((a) => a.anchor(bg).center(label));
    return b.con([bg, label]);
  });
  return makeButton({
    obj: button,
    onClick: () => {
      if (withSound) events.emit("uiClick");
      onClick();
    },
    onHover: () => {
      if (withSound) events.emit("uiHover");
    },
    onOut: () => events.emit("uiOut"),
  });
}

interface IHelpButtonProps {
  scene: Phaser.Scene;
  events: Phaser.Events.EventEmitter;
  text: string;
  onClick: () => void;
}

/** Золотая ссылка «? Помощь» для тёмной панели: знак вопроса в кольце и подпись. */
export function helpButton({ scene, events: emitter, text, onClick }: IHelpButtonProps) {
  const events = new SafeEventsAdapter<IUiEvents>(emitter);
  const button = makeView(scene, (b) => {
    const ring = b.circle({
      color: uiColors.dark,
      size: 19,
      strokeColor: uiColors.gold,
      strokeWidth: 3,
    });
    const mark = b.text({
      text: "?",
      style: { fontFamily: uiFonts.interSemibold.fontFamily, fontSize: 28, color: uiColors.gold },
    });
    const label = b.text({
      text,
      style: { fontFamily: uiFonts.interSemibold.fontFamily, fontSize: 32, color: uiColors.gold },
    });
    makeAlign((a) => {
      a.anchor(ring).center(mark, 0, -1);
      a.anchor(ring).rightTo(label, 14).centerY(label);
    });
    return b.con([ring, mark, label]);
  });
  return makeButton({
    obj: button,
    onClick: () => {
      events.emit("uiClick");
      onClick();
    },
    onHover: () => events.emit("uiHover"),
    onOut: () => events.emit("uiOut"),
  }).setName("help");
}

interface IConsumableButtonProps {
  scene: Phaser.Scene;
  events: Phaser.Events.EventEmitter;
  iconName?: IconName;
  onClick: () => void;
  /** Доступна ли реклама: при нуле зарядов рисуется значок ▶ вместо числа. */
  isRewardModeEnabled: () => boolean;
}

/** Кнопка расходника: иконка, круглый бейдж-счётчик и значок «плей» вместо счётчика при нуле. */
export function consumableMagicButton({
  iconName = "magic",
  scene,
  events: emitter,
  onClick,
  isRewardModeEnabled,
}: IConsumableButtonProps) {
  const events = new SafeEventsAdapter<IUiEvents>(emitter);
  const badgeOffset = getBadgeOffset(iconName);

  const iconSize = 128;
  const badgeSize = 50;
  const rewardIconSize = 30;
  const badgeCenterTop = (iconSize - badgeSize) / 2;

  return CindUi.consumableButton({
    scene,
    imageAsset: getImageAsset(iconAssets[iconName]),
    imageWidth: iconSize,
    imageHeight: iconSize,
    badgeAsset: getImageAsset("badgeRoundGlossyGreen"),
    badgeWidth: badgeSize,
    badgeHeight: badgeSize,
    badgeTopOffset: badgeCenterTop + badgeOffset.y,
    badgeOffsetX: badgeOffset.x,
    badgeContentOffsetY: 0,
    valueStyle: uiTextStyle(22, uiColors.cream),
    rewardIconAsset: getImageAsset("iconPlay"),
    rewardIconWidth: rewardIconSize,
    rewardIconHeight: rewardIconSize,
    initValue: 0,
    isRewardModeEnabled,
    onClick: () => {
      events.emit("uiClick");
      onClick();
    },
  }).setName(iconName);
}

/** Сдвиг бейджа от центра иконки: у магии монета ниже и ближе к центру, у остальных — выше и правее. */
function getBadgeOffset(iconName: IconName): { x: number; y: number } {
  if (iconName === "magic") return { x: 25, y: 40 };

  return { x: 30, y: 20 };
}
