import type { IGameCoreSoundConfig } from "@kvisaz/phaser-common";
import type { IGameSoundEvents } from "../services/sound/events";
import { autoAssetsConfig } from "../autoAssetsConfig";

/** Настройки звука текущего запуска: единственный источник истины меню, демо и диалогов. */
export interface ISoundSettings {
  isSoundOn: boolean;
  isMusicOn: boolean;
}

/** Текущие настройки: звук и музыка включены, выбор игрока восстанавливается из сохранения. */
export const soundSettings: ISoundSettings = { isSoundOn: true, isMusicOn: true };

const sounds = {
  cardReject: autoAssetsConfig.sounds.cardSfx03.name,
  transfer: autoAssetsConfig.sounds.cardFlip.name,
  recycleDeck: autoAssetsConfig.sounds.cardMultipleFlip.name,
  base: autoAssetsConfig.sounds.cashRegister.name,
  uiClick: autoAssetsConfig.sounds.click.name,
  uiHover: autoAssetsConfig.sounds.cardFlip.name,
} as const;

/** Единые звуки пяти пасьянсов и UI; настройки и временный mute применяет GameSoundService. */
export const soundConfig: IGameCoreSoundConfig<IGameSoundEvents> = {
  initialSettings: { ...soundSettings },
  /** фоновая музыка в цикле; громкость — как у старого Паука **/
  music: { soundName: autoAssetsConfig.sounds.music.name, volume: 0.09 },
  effects: {
    onMoveStarted: (scene, { type }) => {
      /** добор колоды озвучивают шаги раздачи — по карте **/
      if (type === "dealFromDeckMultiple") return;
      scene.sound.play(type === "recycle" ? sounds.recycleDeck : sounds.transfer, { volume: 1.0 });
    },
    /** карта легла на базу: касса звенит вместе с конфетти на первой и последней карте базы, у Паука — на собранной масти **/
    cardToBase: (scene) => scene.sound.play(sounds.base, { volume: 0.2 }),
    cardDeal: (scene) => scene.sound.play(sounds.transfer, { volume: 1.0 }),
    spiderDealGroupStep: (scene) => scene.sound.play(sounds.transfer, { volume: 1.0 }),
    cardReject: (scene) => scene.sound.play(sounds.cardReject, { volume: 0.5 }),
    uiClick: (scene) => scene.sound.play(sounds.uiClick, { volume: 0.5 }),
    uiHover: (scene) => scene.sound.play(sounds.uiHover, { volume: 0.2 }),
    uiToggle: (scene) => scene.sound.play(sounds.transfer, { volume: 0.5 }),
  },
};
