import { makeAlign, makeView } from "@kvisaz/phaser-common";
import { iconButton } from "../../../../shared/buttons";
import { DialogShell } from "../../../../shared/dialog/DialogView/components/DialogShell";
import { uiTextStyle } from "../../../../shared/style";
import { helpViewConfig } from "./config";

interface IHelpViewProps {
  scene: Phaser.Scene;
  events: Phaser.Events.EventEmitter;
  title: string;
  /** правила готовым текстом: абзацы разделены пустой строкой */
  text: string;
  close(): void;
}

/**
 * Правила одной игры: окно с шапкой и текстом под ней.
 * Props не хранит: у DialogShell уже есть приватное поле props, одноимённое поле наследника не собрать.
 */
export class HelpView extends DialogShell {
  constructor({ scene, events, title, text, close }: IHelpViewProps) {
    super({
      scene,
      title,
      height: helpViewConfig.height,
      closeButton: iconButton({ scene, events, name: "close", onClick: close }),
    });
    const { left, top, width, fontSize } = helpViewConfig.textBlock;

    const textView = makeView(scene, (b) =>
      b.text({ text, style: { ...uiTextStyle(fontSize), wordWrap: { width } } }),
    );
    makeAlign((a) => a.anchor(this.bg).leftIn(textView, left).topIn(textView, top));

    this.add(textView);
  }
}
