import { solitaireIds, type SolitaireId } from "../../configs/config.games";
import type { IGameScore, IPlayerData, ISolitairesSave, ISoundState, SoundSave } from "./types";

/**
 * Мост между компактным форматом сохранения и обычными данными игры, как в старом Пауке:
 * чистые функции, сохранение не трогают.
 */

/** Целое неотрицательное число или 0: сохранение могли испортить. */
function count(value: unknown): number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0 ? value : 0;
}

/** Чистит загруженное сохранение: битые поля отбрасываются, остальное остаётся. */
export function sanitizeSave(data: ISolitairesSave | undefined): ISolitairesSave {
  if (data == null || typeof data !== "object") return {};
  return {
    ...(count(data.f) ? { f: data.f } : {}),
    ...(Array.isArray(data.s) ? { s: [data.s[0] ? 1 : 0, data.s[1] ? 1 : 0] } : {}),
    ...(data.g && typeof data.g === "object" && !Array.isArray(data.g)
      ? {
          g: Object.fromEntries(
            solitaireIds.map((id) => {
              const last = count(data.g?.[id]?.l);
              return [id, { m: Math.max(count(data.g?.[id]?.m), last), l: last }];
            }),
          ),
        }
      : {}),
    ...(data.counter != null ? { counter: count(data.counter) } : {}),
    ...(data.m != null ? { m: count(data.m) } : {}),
    ...(typeof data.w === "boolean" ? { w: data.w } : {}),
  };
}

export function toSound([sound, music]: SoundSave): ISoundState {
  return { isSoundOn: sound === 1, isMusicOn: music === 1 };
}

export function fromSound({ isSoundOn, isMusicOn }: ISoundState): SoundSave {
  return [isSoundOn ? 1 : 0, isMusicOn ? 1 : 0];
}

/** Данные игрока из загруженного (уже очищенного) сохранения: недостающее — по умолчанию. */
export function toPlayerData(save: ISolitairesSave): IPlayerData {
  return {
    firstStartAt: save.f,
    sound: save.s ? toSound(save.s) : undefined,
    scores: Object.fromEntries(
      solitaireIds.map((id) => [
        id,
        {
          maxScore: save.g?.[id]?.m ?? 0,
          lastScore: save.g?.[id]?.l ?? 0,
        },
      ]),
    ) as Record<SolitaireId, IGameScore>,
    counter: save.counter ?? 0,
    magicCharges: save.m ?? 0,
    isWinAnimationAllowed: save.w ?? true,
  };
}

/** Компактное сохранение из данных игрока: значения по умолчанию не пишутся. Вызывается на каждую запись — без лишних объектов. */
export function fromPlayerData(data: IPlayerData): ISolitairesSave {
  const { firstStartAt, sound, scores, counter, magicCharges, isWinAnimationAllowed } = data;
  const save: ISolitairesSave = {};
  if (firstStartAt) save.f = firstStartAt;
  if (sound) save.s = fromSound(sound);
  if (solitaireIds.some((id) => scores[id].maxScore > 0)) {
    save.g = Object.fromEntries(
      solitaireIds.map((id) => [
        id,
        {
          m: scores[id].maxScore,
          l: scores[id].lastScore,
        },
      ]),
    );
  }
  if (counter) save.counter = counter;
  if (magicCharges) save.m = magicCharges;
  if (!isWinAnimationAllowed) save.w = false;
  return save;
}
