import { onSceneShutdown, SafeEventsAdapter, UnSubManager } from "@kvisaz/phaser-common";
import { SCENES, type SolitaireId } from "../../scenes";
import { services } from "../../services";
import { SolitaireView } from "./SolitaireView/SolitaireView";
import type { ISolitaireEvents } from "./SolitaireView/events";

/** Одна обычная сцена партии для пяти конфигураций пасьянса. */
export class SolitaireScene extends Phaser.Scene {
  private readonly unSubs = new UnSubManager();
  private gameId!: SolitaireId;

  /** Регистрирует общую сцену партии. */
  constructor() {
    super(SCENES.solitaire);
  }

  /** Получает выбранный пасьянс при запуске сцены. */
  init({ gameId }: { gameId: SolitaireId }): void {
    this.gameId = gameId;
  }

  /** Собирает существующую партию без общего родителя и подмены View. */
  create(): void {
    const { adsService, gameEvents, locale, playerDataService } = services;
    const scene = this;
    const { t, lang } = locale;

    /** Адаптер хранит подписки только этого запуска сцены. */
    const events = new SafeEventsAdapter<ISolitaireEvents>(gameEvents);
    this.unSubs.addUnSub(() => events.unSubscribeAll());

    /** После подтверждения и рекламы экран сам выполняет переход. */
    events.on("requestMenuScreen", () => {
      this.scene.start(SCENES.menu);
    });
    events.on("requestGameScreen", ({ gameId }) => {
      this.scene.restart({ gameId });
    });

    /** Партия получает выбранную игру, сохранённые заряды и настройки. */
    this.unSubs.addUnSub(
      new SolitaireView({
        scene,
        events: gameEvents,
        t,
        gameId: this.gameId,
        magicCharges: playerDataService.getData().magicCharges,
        saveMagicCharges: (value) => {
          void playerDataService.patch(() => ({ magicCharges: value })).flush();
        },
        isWinAnimationAllowed: () => playerDataService.getData().isWinAnimationAllowed,
        onWinAnimationAllowedChange: (value) => {
          void playerDataService.patch(() => ({ isWinAnimationAllowed: value })).flush();
        },
        isRewardedAvailable: () => adsService.isRewardAdEnabled,
      }),
    );

    /** При уходе удаляем партию и её обработчики переходов. */
    this.unSubs.addUnSub(onSceneShutdown(scene, () => this.unSubs.destroy()));

    /** Название вкладки показывает текущий пасьянс. */
    document.title = `${t(this.gameId)} — ${t("title")}`;
    document.documentElement.lang = lang;
  }
}
