import { arrayAlign, makeAlign } from "@kvisaz/phaser-common";
import type { SolitaireLayout } from "../types";

/**
 * 40 разбойников: десять колонок, над колонками 3–10 восемь баз, левее них колода и сброс.
 * Шаг у обоих рядов один, поэтому базы стоят точно над колонками. Колода со сбросом отодвинуты от баз сильнее шага
 * и выступают влево за стол, как ячейки у Свободной ячейки. Всё поле прижато к правому краю экрана.
 */
export const layoutFortyThieves: SolitaireLayout = (
  scene,
  { tables, bases, stock, waste },
  config,
) => {
  /** Свой шаг по горизонтали: десять колонок при масштабе 0.9 не помещаются с общим шагом, px. */
  const stepX = 20;
  /** Пустота между сбросом и первой базой, px. */
  const groupsGap = 180;
  /** Отступ правого края поля от края экрана, px. */
  const rightMarginX = 10;
  const { cardsTopY } = config;
  const tableTopY = cardsTopY + stock!.getBounds().height + config.placeGap;
  makeAlign((a) => {
    a.row(bases, stepX);
    a.row([stock!, waste!], stepX);
    const baseRow = arrayAlign.alignObject(bases);
    a.anchor(baseRow).leftTo(arrayAlign.alignObject([stock!, waste!]), -groupsGap);
    a.anchorSceneScreen(scene).topIn(arrayAlign.alignObject([stock!, waste!, ...bases]), cardsTopY);
    a.row(tables, stepX);
    const tableRow = arrayAlign.alignObject(tables);
    a.anchor(baseRow).rightIn(tableRow);
    a.anchorSceneScreen(scene).topIn(tableRow, tableTopY);
    const allPlaces = arrayAlign.alignObject([stock!, waste!, ...bases, ...tables]);
    a.anchorSceneScreen(scene).rightIn(allPlaces, -rightMarginX);
  });
};
