import type { IBaseScorer } from "../types";

interface ICardsOnBasesScorerProps {
  maxBase: number;
  perCard?: number;
  /** надбавка за полностью собранную базу */
  perFullBase?: number;
  fullBaseSize?: number;
  /** роль стопок баз: движок строит stackId как `${type}-${index}` */
  baseType?: string;
}

/** Очки за карты на базах и надбавка за собранную базу: Косынка, FreeCell, Юкон — 1 за карту; Сорок разбойников — 5 + 60. */
export function cardsOnBasesScorer({
  maxBase,
  perCard = 1,
  perFullBase = 0,
  fullBaseSize = 13,
  baseType = "base",
}: ICardsOnBasesScorerProps): IBaseScorer {
  return {
    maxBase,
    count: (stacks) =>
      [...stacks]
        .filter(([stackId]) => stackId.startsWith(`${baseType}-`))
        .reduce(
          (sum, [, cards]) =>
            sum + cards.length * perCard + (cards.length === fullBaseSize ? perFullBase : 0),
          0,
        ),
  };
}
