/** Карта, как её видит подсчёт очков: местный алиас, без типов игр и библиотеки. */
export interface IScoreCard {
  readonly stackId: string;
  readonly suit: string;
  readonly value: string | number;
  readonly isFaceUp: boolean;
}

/** Карта на сцене: порядок в стопке берётся из порядка отрисовки. */
export type ScoreCardObject = Phaser.GameObjects.GameObject & IScoreCard;

/** Стопки по stackId, карты в каждой — снизу вверх. */
export type ScoreStacks = ReadonlyMap<string, readonly IScoreCard[]>;

/** Стратегия игры: как считать основу по раскладу и её максимум. */
export interface IBaseScorer {
  readonly maxBase: number;
  count(stacks: ScoreStacks): number;
}

/** Пороги бонусов: [быстро, медленно]. */
export interface IScoreLimits {
  readonly timeSec: readonly [number, number];
  readonly moves: readonly [number, number];
}

/** Данные от игры: только изменившиеся поля. Время и ходы ведёт игра. */
export interface IScoreData {
  cards?: readonly ScoreCardObject[];
  seconds?: number;
  moves?: number;
}

/** Итог сеанса: основа за базы и бонусы. */
export interface ISessionScore {
  bases: number;
  time: number;
  moves: number;
  /** основа и оба бонуса */
  total: number;
}
