import { makeAlign } from "@kvisaz/phaser-common";
import type { ILeaderboardRow } from "../types";
import { leaderboardConfig } from "../config";
import { LeaderboardRow } from "../LeaderboardRow/LeaderboardRow";
import { LeaderboardRowDivider } from "../LeaderboardRowDivider/LeaderboardRowDivider";

interface ILeaderboardTableProps {
  scene: Phaser.Scene;
  /** видимые строки по месту */
  rows: ILeaderboardRow[];
  /** строка игрока — с этим rank; нет — строка игрока с rank 0 */
  playerRank?: number;
  /** имена по умолчанию, когда публичного имени нет */
  youText: string;
  anonymousText: string;
}

/**
 * Таблица рейтинга: строки LeaderboardRow по месту, «…» на разрывах мест.
 * Ставит строки колонкой и анимирует въезд; положение задаёт окно, затем вызывает start().
 */
export class LeaderboardTable extends Phaser.GameObjects.Container {
  /** item — строка или разделитель; row — только для строки: у неё набегают очки */
  private readonly rows: {
    item: Phaser.GameObjects.Container;
    row?: LeaderboardRow;
    isPlayer?: boolean;
  }[];

  constructor(private props: ILeaderboardTableProps) {
    super(props.scene, 0, 0);
    const { scene, rows, playerRank = 0, youText, anonymousText } = this.props;
    const { rowGap, maxRows } = leaderboardConfig;
    const digits = String(Math.max(0, ...rows.map(({ score }) => score))).length;

    const buildRow = (data: ILeaderboardRow, prev?: ILeaderboardRow) => {
      // «…» — только при разрыве в местах: строки подряд идут без разделителя.
      const gap =
        prev && data.rank !== prev.rank + 1 ? [{ item: new LeaderboardRowDivider({ scene }) }] : [];
      const isPlayer = data.rank === playerRank;
      const name = data.name || (isPlayer ? youText : anonymousText);
      const row = new LeaderboardRow({
        scene,
        rank: data.rank,
        name,
        score: data.score,
        digits,
        isPlayer,
      });
      return [...gap, { item: row, row, isPlayer }];
    };

    // Игрок без места (rank 0) стоит последней строкой: заполнители идут перед ним.
    const unranked = rows[rows.length - 1]?.rank === 0 ? rows[rows.length - 1] : undefined;
    const ranked = unranked ? rows.slice(0, -1) : rows;
    this.rows = ranked.flatMap((data, i) => buildRow(data, ranked[i - 1]));

    // Таблица всегда на maxRows строк: пустые — с продолжением нумерации, «…» вместо имени, «—» вместо очков.
    const fillCount = Math.max(0, maxRows - this.rows.length - (unranked ? 1 : 0));
    let rank = ranked[ranked.length - 1]?.rank ?? 0;
    for (let i = 0; i < fillCount; i++) {
      const item = new LeaderboardRow({
        scene,
        rank: ++rank,
        name: "…",
        score: 0,
        digits,
        isPlayer: false,
        isEmpty: true,
      });
      this.rows.push({ item, row: item });
    }
    if (unranked)
      this.rows.push(...buildRow(unranked, fillCount ? undefined : ranked[ranked.length - 1]));
    const items = this.rows.map(({ item }) => item);
    if (items.length) makeAlign((a) => a.column(items, rowGap));
    this.add(items);
  }

  /** Запускает въезд строк и набег очков. */
  start(): void {
    const { scene } = this.props;
    const { rowGap, staggerMs, slideMs, slideX, riseRows } = leaderboardConfig;
    const bottomY = this.rows[this.rows.length - 1].item.y;
    this.rows.forEach(({ item, row, isPlayer }, i) => {
      const { x, y } = item;
      // Строка игрока всплывает снизу: от нижней видимой строки, но не дальше riseRows строк от своего места.
      const rise = isPlayer
        ? Math.min(riseRows * (item.getBounds().height + rowGap), bottomY - y)
        : 0;
      item.setPosition(x + (rise ? 0 : slideX), y + rise).setAlpha(0);
      scene.tweens.add({
        targets: item,
        x,
        y,
        alpha: 1,
        duration: rise ? slideMs * 2 : slideMs,
        delay: i * staggerMs,
        ease: Phaser.Math.Easing.Cubic.Out,
        onStart: () => row?.start(),
        onComplete: () => {
          if (isPlayer)
            scene.tweens.add({ targets: item, alpha: 0.6, duration: 220, yoyo: true, repeat: 1 });
        },
      });
    });
  }

  destroy(fromScene?: boolean) {
    this.props.scene.tweens.killTweensOf(this.rows.map(({ item }) => item));
    super.destroy(fromScene);
  }
}
