import { makeAlign, makeView } from "@kvisaz/phaser-common";
import { CountUpText } from "../../../CountUpText/CountUpText";
import { uiTextStyle } from "../../../style";
import { dialogViewConfig } from "../../config";

interface IScoreBlockProps {
  scene: Phaser.Scene;
  /** очки сеанса: основа за базы, бонусы и итог — их сумма */
  bases: number;
  time: number;
  moves: number;
  total: number;
  /** уже переведённые подписи */
  texts: { total: string; bases: string; time: string; moves: string; place: string };
  /** есть — в строке итога справа ждёт место в рейтинге: его задаёт setPlaceRank */
  hasPlace: boolean;
}

/**
 * Блок очков в диалогах победы и тупика: итог и три слагаемых. Цифр столько, сколько в итоге.
 * Слагаемые набегают по очереди, итог — одновременно со всеми ними; набег стартует при создании.
 */
export class ScoreBlock extends Phaser.GameObjects.Container {
  private place?: { separator: Phaser.GameObjects.Text; label: Phaser.GameObjects.Text };

  constructor(private props: IScoreBlockProps) {
    super(props.scene, 0, 0);
    const { scene, bases, time, moves, total, texts, hasPlace } = this.props;
    const { delayMs, durationMs, totalFontSize, partFontSize, rowGap, labelGap } = dialogViewConfig;
    const digits = String(total).length;
    const totalStyle = uiTextStyle(totalFontSize);
    const partStyle = uiTextStyle(partFontSize);
    const counter = (value: number, style: typeof partStyle, duration: number, delay: number) =>
      new CountUpText({ scene, value, digits, style, durationMs: duration, delayMs: delay });

    const partData = [
      [bases, texts.bases],
      [time, texts.time],
      [moves, texts.moves],
    ] as const;
    const totalCounter = counter(total, totalStyle, durationMs * partData.length, delayMs);
    const partCounters = partData.map(([value], i) =>
      counter(value, partStyle, durationMs, delayMs + i * durationMs),
    );

    makeView(scene, (b) => {
      const totalLabel = b.text({ text: texts.total, style: totalStyle });
      const partLabels = partData.map(([, text]) => b.text({ text, style: partStyle }));
      const separator = hasPlace ? b.text({ text: "·", style: partStyle }) : undefined;
      const placeLabel = hasPlace ? b.text({ text: "", style: partStyle }) : undefined;
      if (separator && placeLabel) this.place = { separator, label: placeLabel };

      makeAlign((a) => {
        a.anchor(totalLabel).rightTo(totalCounter, labelGap).centerY(totalCounter);
        if (separator && placeLabel) {
          a.anchor(totalCounter).rightTo(separator, labelGap).centerY(separator);
          a.anchor(separator).rightTo(placeLabel, labelGap).centerY(placeLabel);
        }
        // Числа — колонкой по левому краю итога, подписи слагаемых — общей колонкой правее.
        let last: Phaser.GameObjects.Text = totalLabel;
        partCounters.forEach((partCounter, i) => {
          a.anchor(last).bottomTo(partCounter, rowGap);
          a.anchor(totalCounter).leftIn(partCounter);
          a.anchor(partCounters[0]).rightTo(partLabels[i], labelGap);
          a.anchor(partCounter).centerY(partLabels[i]);
          last = partCounter;
        });
      });
      this.add([
        totalLabel,
        totalCounter,
        ...(separator && placeLabel ? [separator, placeLabel] : []),
        ...partCounters.flatMap((partCounter, i) => [partCounter, partLabels[i]]),
      ]);
      return totalLabel;
    });
    [totalCounter, ...partCounters].forEach((c) => c.start());
  }

  /** Место игрока в рейтинге справа от итога; без места строка пуста и разделитель скрыт. */
  setPlaceRank(rank?: number) {
    const {
      place,
      props: { texts },
    } = this;
    if (!place) return;
    place.label.setText(rank == null ? "" : `${texts.place} ${rank}`);
    place.separator.setVisible(rank != null);
  }
}
