import {
  delay,
  SafeEventsAdapter,
  UnSubManager,
  type LeaderboardService as LeaderboardsApi,
  type YandexSdkWrapperV2,
} from "@kvisaz/phaser-common";
import { solitaireIds, type SolitaireId } from "../../configs/config.games";
import { leaderboardConfig } from "../../configs/config.leaderboard";
import type { PlayerDataService } from "../playerData/PlayerDataService";
import type { ILeaderboardEvents, ILeaderboardResult } from "./types";

interface ILeaderBoardServiceProps {
  events: Phaser.Events.EventEmitter;
  leaderboards: LeaderboardsApi;
  playerDataService: PlayerDataService;
}

/** Хранит результаты игр и отправляет рекорды через облачный или виртуальный транспорт. */
export class LeaderBoardService {
  private readonly unSubs = new UnSubManager();
  private writes = Promise.resolve();
  private lastWriteAt = 0;
  private destroyed = false;

  /** Подписывается один раз; смена игровых экранов сервис не пересоздаёт. */
  constructor(private readonly props: ILeaderBoardServiceProps) {
    const events = new SafeEventsAdapter<ILeaderboardEvents>(props.events);
    this.unSubs.addUnSub(() => events.unSubscribeAll());
    events.on("solitaireResult", ({ gameId, score }) => {
      void this.setScore(gameId, score).catch((error: unknown) =>
        console.warn("Leaderboard result:", error),
      );
    });
  }

  /** После подготовки SDK и PlayerData подключает транспорт. */
  preload(platform: YandexSdkWrapperV2): void {
    const sdk = platform.getSDK();
    this.props.leaderboards.start(
      sdk
        ? {
            leaderboards: sdk.leaderboards,
            isAuthorized: () => platform.getPlayer()?.isAuthorized() ?? false,
          }
        : undefined,
    );
  }

  /** Следует доступности выбранного транспорта, без подмены облака при ошибке. */
  enabled(): boolean {
    return this.props.leaderboards.enabled();
  }

  /** Таблица доступна и у игрока есть положительный локальный рекорд для неё. */
  isTableWithPlayer(board: SolitaireId): boolean {
    if (!this.enabled()) return false;
    const { scores } = this.props.playerDataService.getData();
    return scores[board].maxScore > 0;
  }

  /** Сохраняет последний результат и максимум; в обе доски отправляет только рекорды. */
  setScore(gameId: SolitaireId, score: number): Promise<void> {
    const { playerDataService } = this.props;
    playerDataService.patch(({ scores }) => {
      const result = scores[gameId];
      result.lastScore = score;
      result.maxScore = Math.max(result.maxScore, score);
      return { scores };
    });
    void playerDataService
      .flush()
      .catch((error: unknown) => console.warn("Leaderboard save:", error));
    if (!this.enabled()) return Promise.resolve();

    /** Последовательная отправка соблюдает лимит SDK и не даёт старому рекорду обогнать новый. */
    this.writes = this.writes.then(async () => {
      for (const board of [gameId, "all"] as const) {
        await delay(
          Math.max(0, leaderboardConfig.writeIntervalMs - (Date.now() - this.lastWriteAt)),
        );
        if (this.destroyed) return;
        const { scores } = playerDataService.getData();
        const value =
          board === "all"
            ? solitaireIds.reduce((sum, id) => sum + scores[id].maxScore, 0)
            : scores[board].maxScore;
        this.lastWriteAt = Date.now();
        try {
          await this.props.leaderboards.setScore(board, value);
        } catch (error) {
          console.warn(`Leaderboard ${board}:`, error);
        }
      }
    });
    return this.writes;
  }

  /** Доска игры читается при открытии окна, после отправки уже поставленных рекордов. */
  async getEntries(board: SolitaireId): Promise<ILeaderboardResult> {
    await this.writes;
    if (!this.enabled()) throw new Error("Leaderboards unavailable");
    const { entries, userRank } = await this.props.leaderboards.getEntries(board, {
      quantityTop: leaderboardConfig.top,
      quantityAround: leaderboardConfig.around,
      includeUser: true,
    });
    return {
      rows: entries.map(({ rank, score, player }) => ({ rank, score, name: player.publicName })),
      playerRank: userRank || undefined,
      status: "ready",
    };
  }

  /** Снимает только свои подписки и прекращает ещё не отправленные записи. */
  destroy(): void {
    this.destroyed = true;
    this.unSubs.destroy();
  }
}
