import { arrayAlign, makeAlign } from "@kvisaz/phaser-common";
import type { SolitaireLayout } from "../types";

/**
 * Паук: десять колонок по центру; над ними колода у левого края стола и восемь баз у правого, над колонками 3–10.
 * Шаг у обоих рядов один.
 */
export const layoutSpider: SolitaireLayout = (scene, { tables, bases, stock }, config) => {
  /** Шаг по горизонтали у обоих рядов, px. */
  const stepX = 24;
  /** Сдвиг центра поля по X, px. */
  const centerXOffset = 96;
  /** От верха карт до верха колонок, px. */
  const tableRowOffsetY = 240;
  const { cardsTopY } = config;
  makeAlign((a) => {
    a.row(tables, stepX);
    const tableBounds = arrayAlign.alignObject(tables);
    a.anchorSceneScreen(scene)
      .centerX(tableBounds, centerXOffset)
      .topIn(tableBounds, cardsTopY + tableRowOffsetY);
    a.row(bases, stepX);
    const baseRow = arrayAlign.alignObject(bases);
    a.anchor(tableBounds).leftIn(stock!).rightIn(baseRow);
    a.anchorSceneScreen(scene).topIn(stock!, cardsTopY).topIn(baseRow, cardsTopY);
  });
};
