import {
  adaptiveHiddenOpenTailCardLayoutStrategy,
  fromTopCardLayoutStrategy,
  makeView,
  type ICardPlace,
  type ILayoutStrategy,
} from "@kvisaz/phaser-common";
import type { ISolitaireConfig } from "./types";

/** Запас, сброс, ячейки и базы — плотная стопка, как в сторях движка. */
export const stackLayout: ILayoutStrategy = (items, zone) =>
  fromTopCardLayoutStrategy(items, zone, { cardOffset: 0, marginTop: 0 });

interface IPlaceViewProps {
  scene: Phaser.Scene;
  /** base — тёмное место базы, остальные — обычные. */
  type: string;
  width: number;
  height: number;
}

/** Прямоугольник места под карту, под картами по глубине. */
export function placeView({ scene, type, width, height }: IPlaceViewProps): ICardPlace {
  return makeView(scene, (b) =>
    b.rect({
      width,
      height,
      color: type === "base" ? "#103a2c" : "#174737",
      strokeColor: "#739583",
      strokeWidth: 1,
    }),
  ).setDepth(-1);
}

/** Колонка: закрытые шагом закрытых, открытые — шагом открытых, сжатие под низ экрана. Место карты не зависит от хвоста и переворота. */
export function tableLayout(config: ISolitaireConfig, bottomBoundaryY: number): ILayoutStrategy {
  return (items, target) =>
    adaptiveHiddenOpenTailCardLayoutStrategy(items, target, {
      marginTop: config.marginTop,
      bottomBoundaryY,
      hiddenOffsetY: config.hiddenOffsetY,
      maxHiddenOffsetCards: config.maxHiddenOffsetCards,
      minVisibleOffsetY: config.minVisibleOffsetY,
      maxVisibleOffsetY: config.maxVisibleOffsetY,
    });
}
