import { makeAlign, onSceneShutdown, SafeEventsAdapter, UnSubManager } from "@kvisaz/phaser-common";
import { SCENES } from "../../scenes";
import { services } from "../../services";
import { DemoView } from "./DemoView/DemoView";
import { demoScreenButton } from "./DemoView/components/demoScreenButton";
import type { IDemoEvents } from "./DemoView/events";

/** Самостоятельная сцена стенда сохранений, звука и рекламы. */
export class DemoScene extends Phaser.Scene {
  private readonly unSubs = new UnSubManager();

  /** Регистрирует сцену стенда. */
  constructor() {
    super(SCENES.demo);
  }

  /** Создаёт стенд и кнопку возврата в меню. */
  create(): void {
    const { adsService, gameEvents, locale, playerDataService } = services;
    const scene = this;
    const { t, lang } = locale;

    /** Адаптер хранит подписки только этого запуска сцены. */
    const events = new SafeEventsAdapter<IDemoEvents>(gameEvents);
    this.unSubs.addUnSub(() => events.unSubscribeAll());

    /** Стенд сам обрабатывает возврат в меню и свой перезапуск. */
    events.on("requestMenuScreen", () => {
      this.scene.start(SCENES.menu);
    });

    /** Передаём стенду данные, сохранение и доступные действия. */
    this.unSubs.addUnSub(
      new DemoView({
        scene,
        events: gameEvents,
        t,
        getCounter: () => playerDataService.getData().counter,
        saveCounter: (value) => playerDataService.patch(() => ({ counter: value })).flush(),
        getLanguage: () => locale.lang,
        setLanguage: (value) => locale.setLanguage(value),
        isFullscreenAvailable: () => adsService.isFullAdEnabled,
        isRewardedAvailable: () => adsService.isRewardAdEnabled,
      }),
    );

    /** Кнопка возврата сообщает о выборе, переход выполняет сцена. */
    const back = demoScreenButton({ scene, events: gameEvents }, t("back_to_menu"), () =>
      events.emit("requestMenuScreen"),
    );
    this.unSubs.addUnSub(back);
    makeAlign((a) => a.anchorSceneScreen(scene).centerX(back).topIn(back, 32));

    /** При уходе удаляем стенд и снимаем его подписки. */
    this.unSubs.addUnSub(onSceneShutdown(scene, () => this.unSubs.destroy()));

    /** Название вкладки и язык страницы соответствуют выбранной локали. */
    document.title = `${t("demo_title")} — ${t("title")}`;
    document.documentElement.lang = lang;
  }
}
