const fadeSmoothConfig = {
  dataKey: "_smooth_faded",
  durationMs: 350,
  delayToFade: 100,
};

/** Любой объект с прозрачностью; тинта может не быть, например у контейнера. */
type IFadeTarget = Phaser.GameObjects.GameObject & {
  alpha: number;
  setAlpha(value: number): unknown;
  tintTopLeft?: number;
  setTint?(value: number): unknown;
};

interface IFadeSmoothProps {
  obj: IFadeTarget;
  /** true — перейти в состояние fade, false — вернуться к исходному виду. */
  faded: boolean;
  /** Тинт в состоянии fade; не задан — тинт не меняется. */
  tint?: number;
  /** Прозрачность в состоянии fade; не задана — прозрачность не меняется. */
  alpha?: number;
  /** Длительность полного перехода, мс; 0 — сразу. */
  durationMs?: number;
  /** Пауза перед затенением, мс; возврат идёт без паузы. При durationMs 0 не действует. */
  delayToFade?: number;
}

/** Состояние перехода: лежит одним объектом в data, твин меняет его поля без событий data. */
interface IFadeState {
  /** Куда идёт переход: 0 — исходный вид, 1 — fade. */
  target: number;
  progress: number;
  baseTint: number;
  baseAlpha: number;
}

/**
 * Плавно переводит объект в состояние fade или возвращает из него.
 * Повторный вызов с тем же faded ничего не делает, прерванный переход продолжается с текущего вида.
 * Настройки tint и alpha в обоих направлениях должны совпадать.
 *
 * Пример использования - поиск подсказки асинхронный в 5 пасьянсах
 * - Быстрый поиск подсказки: если подсказка нашлась быстрее 100 мс,
 *      кнопка вообще не изменит цвет, так что мигания в этом случае не будет.
 * - Клики: задержка касается только цвета.
 *    Выключенная кнопка сразу перестаёт нажиматься,
 *    поэтому в эти 100 мс она выглядит активной, но клик не сработает.
 * - Повторное затенение: если кнопка возвращалась и не успела посветлеть полностью,
 *    она замрёт на текущем оттенке на 100 мс и потом продолжит темнеть.
 *
 * TODO если пройдет тест и докажет себя в проде - перевести в 00-phaser-common в утилиты
 */
export function fadeSmooth(props: IFadeSmoothProps) {
  const {
    obj,
    faded,
    durationMs = fadeSmoothConfig.durationMs,
    delayToFade = fadeSmoothConfig.delayToFade,
  } = props;
  const { tweens } = obj.scene;
  const state = getFadeState(obj);

  const target = faded ? 1 : 0;
  if (state.target === target) return;
  state.target = target;

  // Выходим из покоя — запоминаем, к чему потом возвращаться.
  if (state.progress === 0) rememberBase(obj, state);

  tweens.killTweensOf(state);

  // Прерванный переход идёт только оставшуюся часть пути.
  const duration = durationMs * Math.abs(target - state.progress);
  if (duration === 0) {
    state.progress = target;
    applyFade(props, state);
    return;
  }

  tweens.add({
    targets: state,
    progress: target,
    duration,
    delay: faded ? delayToFade : 0,
    onUpdate: () => applyFade(props, state),
  });
}

/** Состояние перехода из data объекта; при первом вызове создаёт его и очистку при удалении объекта. */
function getFadeState(obj: IFadeTarget): IFadeState {
  const { dataKey } = fadeSmoothConfig;
  const saved = obj.getData(dataKey) as IFadeState | undefined;
  if (saved != null) return saved;

  const { tweens } = obj.scene;
  const state: IFadeState = { target: 0, progress: 0, baseTint: 0xffffff, baseAlpha: 1 };
  obj.setData(dataKey, state);
  obj.once(Phaser.GameObjects.Events.DESTROY, () => tweens.killTweensOf(state));

  return state;
}

/** Запоминает исходный вид объекта. */
function rememberBase(obj: IFadeTarget, state: IFadeState) {
  state.baseAlpha = obj.alpha;
  state.baseTint = obj.tintTopLeft ?? 0xffffff;
}

/** Применяет вид, соответствующий текущему прогрессу перехода. */
function applyFade({ obj, tint, alpha }: IFadeSmoothProps, state: IFadeState) {
  const { progress, baseAlpha, baseTint } = state;

  if (alpha != null) obj.setAlpha(Phaser.Math.Linear(baseAlpha, alpha, progress));
  if (tint != null) obj.setTint?.(mixColors(baseTint, tint, progress));
}

/** Смешивает два цвета по каналам. */
function mixColors(from: number, to: number, progress: number): number {
  const mix = (shift: number) =>
    Phaser.Math.Linear((from >> shift) & 255, (to >> shift) & 255, progress);

  return Phaser.Display.Color.GetColor(mix(16), mix(8), mix(0));
}
