import { collectStacks } from "./utils/collectStacks";
import type { IBaseScorer, IScoreData, IScoreLimits, ISessionScore } from "./types";

interface ISolitaireScoreLogicProps {
  /** стратегия игры: как считать основу */
  scorer: IBaseScorer;
  limits: IScoreLimits;
  /** доля бонуса от максимума основы, например 0.15 */
  bonusShare: number;
  /** Общая шкала итоговых очков для всех игр. */
  scoreMax: number;
  /** основа изменилась — место для панели */
  onScoreChange?: (bases: number) => void;
}

/**
 * Очки сеанса пасьянса: основа по раскладу через стратегию игры, бонусы за время и ходы — в итоге сеанса.
 * Об играх и партиях модуль не знает: карты, время и ходы игра передаёт через updateData.
 * Формула — раздел «Схема с бонусами» сборника 40_pasyansov_pravila_sovety_ochki_v3.md.
 */
export class SolitaireScoreLogic {
  private bases = 0;
  private seconds = 0;
  private moves = 0;
  private readonly k: number;

  /** Вычисляет коэффициент перевода исходных очков в общую шкалу. */
  constructor(private readonly props: ISolitaireScoreLogicProps) {
    const {
      scorer: { maxBase },
      bonusShare,
      scoreMax,
    } = props;
    this.k = scoreMax / (maxBase + 2 * Math.round(maxBase * bonusShare));
  }

  /** Принимает только изменившиеся поля; основа пересчитывается, когда пришли карты. */
  updateData({ cards, seconds, moves }: IScoreData): void {
    if (seconds != null) this.seconds = seconds;
    if (moves != null) this.moves = moves;
    if (!cards) return;

    const bases = this.props.scorer.count(collectStacks(cards));
    if (bases === this.bases) return;
    this.bases = bases;
    this.props.onScoreChange?.(Math.round(bases * this.k));
  }

  /** Итог сеанса по последним данным: темп незаконченной партии пересчитан на всю раздачу, бонус умножен на долю собранного. */
  getSessionScore(): ISessionScore {
    const {
      scorer: { maxBase },
      limits,
      bonusShare,
    } = this.props;
    const { bases: rawBases, seconds, moves, k } = this;
    const share = rawBases / maxBase;
    const bases = Math.round(rawBases * k);
    if (share <= 0) return { bases, time: 0, moves: 0, total: bases };

    // Сначала прежний целочисленный бонус, затем перевод в общую шкалу.
    const bonus = (value: number, range: readonly [number, number]) =>
      Math.round(Math.round(bonusShare * maxBase * share * bonusFactor(value / share, range)) * k);
    const time = bonus(seconds, limits.timeSec);
    const movesBonus = bonus(moves, limits.moves);
    return { bases, time, moves: movesBonus, total: bases + time + movesBonus };
  }
}

/** Доля бонуса по темпу: 1 при «быстро» и лучше, 0 при «медленно» и хуже, между ними линейно. */
function bonusFactor(value: number, [fast, slow]: readonly [number, number]): number {
  return Math.min(1, Math.max(0, (slow - value) / (slow - fast)));
}
