import {
  CardDanceAnimation,
  cardEngineV1,
  type IDanceCard,
  InputBlocker,
  makeAlign,
  UnSubManager,
} from "@kvisaz/phaser-common";

interface IWinDanceProps {
  scene: Phaser.Scene;
  /** стопки баз: танец берёт их карты снизу вверх **/
  stacks: cardEngineV1.IDragDropCardStack[];
  /** танец доиграл или пропущен кликом; после destroy() не вызывается **/
  onDone: () => void;
}

/** Победный танец: случайная анимация библиотеки по базам, без звуков; клик по экрану пропускает, кнопки на время танца не нажать. */
export class WinDance {
  private readonly unSubs = new UnSubManager();

  constructor(private readonly props: IWinDanceProps) {
    const { scene, stacks, onDone } = props;
    const danceCardsStacks = getStackDanceCards(stacks);
    const dance = CardDanceAnimation.random({ scene, stacks: danceCardsStacks, trail: true });

    /** Пропуск — тот же конец танца: play() выполняется и при destroy() **/
    const skip = () => dance.destroy();
    /** Щит над HUD: кнопки под ним клика не получают, любой клик по щиту — пропуск **/
    const shield = new InputBlocker({ scene }).setDepth(Number.MAX_SAFE_INTEGER);
    makeAlign((align) => align.anchorSceneScreen(scene).center(shield));
    scene.add.existing(shield);
    shield.once(Phaser.Input.Events.GAMEOBJECT_POINTER_DOWN, skip);
    /** после destroy() компонента конец танца уже никого не ждёт **/
    let alive = true;
    this.unSubs.addUnSub([
      () => {
        alive = false;
      },
      shield,
      dance,
    ]);
    /**
     * До onDone поле очищается: щит снят, танец остановлен (Path бежит до destroy()), карты спрятаны.
     * Из победы нет пути назад к столу, поэтому останки танца не должны висеть за диалогом и после него.
     */
    void dance.play().then(() => {
      shield.destroy();
      dance.destroy();
      danceCardsStacks.forEach((cards) => cards.forEach((card) => card.setVisible(false)));
      if (alive) onDone();
    });
  }

  destroy() {
    this.unSubs.destroy();
  }
}

function getStackDanceCards(stacks: cardEngineV1.IDragDropCardStack[]): IDanceCard[][] {
  return stacks.map(({ cards }) => cards) as unknown as IDanceCard[][];
}
