import {
  openCommonModalInScene,
  SafeEventsAdapter,
  UnSubManager,
  type AlignObject,
  type ICommonModalSceneHandle,
} from "@kvisaz/phaser-common";
import { soundSettings } from "../../../configs/config.sound";
import { createDialogView } from "./DialogView/DialogView";
import type { IDialogEvents } from "./events";
import { DialogKind, IDialogScore } from "./types";

/** Содержимое модального окна: библиотека ставит его по центру. */
type ModalContent = Phaser.GameObjects.GameObject & AlignObject;

interface IDialogsProps {
  scene: Phaser.Scene;
  events: Phaser.Events.EventEmitter;
  t(key: string): string;
  isWinAnimationAllowed(): boolean;
  onWinAnimationAllowedChange(value: boolean): void;
}

/** Один диалог на экран. Дочерняя сцена приостанавливает карты и игровой таймер. */
export class Dialogs {
  private readonly unSubs = new UnSubManager();
  private readonly events: SafeEventsAdapter<IDialogEvents>;
  private dialog?: ICommonModalSceneHandle;

  /** Принимает конкретные зависимости, не создавая графических объектов. */
  constructor(private readonly props: IDialogsProps) {
    this.events = new SafeEventsAdapter<IDialogEvents>(props.events);
    this.unSubs.addUnSub(() => this.events.unSubscribeAll());

    // Активный диалог всегда закрывается вместе с экраном, даже если его не закрыли вручную.
    this.unSubs.addUnSub(() => {
      this.dialog?.destroy();
      this.dialog = undefined;
    });
  }

  /** Не даёт рекламной паузе оборота колоды перебить открытый диалог. */
  get isOpen(): boolean {
    return this.dialog != null;
  }

  /** Открывает диалог по виду через библиотечный lifecycle; действие выполняется после закрытия. */
  open(
    kind: DialogKind,
    onConfirm?: () => void,
    onCancel?: () => void,
    score?: IDialogScore,
    reward?: number,
  ) {
    const { t, isWinAnimationAllowed, onWinAnimationAllowedChange } = this.props;
    const { events } = this;
    this.show((scene, close) =>
      createDialogView({
        scene,
        events: this.props.events,
        t,
        kind,
        settings: soundSettings,
        score,
        reward,
        close: () => close(onCancel),
        dismiss: () => close(),
        confirm: () => close(onConfirm),
        onSettingsChange: (settings) => events.emit("coreSoundSettingsChanged", settings),
        isWinAnimationAllowed: isWinAnimationAllowed(),
        onWinAnimationAllowedChange,
      }),
    );
  }

  /** Модальная сцена с затемнением: один диалог за раз, действие — после закрытия. */
  public show(
    createContent: (scene: Phaser.Scene, close: (next?: () => void) => void) => ModalContent,
  ) {
    if (this.dialog) return;
    let action: (() => void) | undefined;
    let closing = false;
    const { scene: parentScene } = this.props;
    const { events } = this;

    /** Повторный клик во время анимации не должен запускать действие дважды. */
    const close = (next?: () => void) => {
      if (closing) return;
      closing = true;
      action = next;
      this.dialog?.close();
    };
    this.dialog = openCommonModalInScene({
      parentScene,
      createContent: (scene) => createContent(scene, close),
      props: {
        overlayAlpha: 0.55,
        overlayColor: "#000000",
        animationDuration: 180,
        isCloseOnOverlayClick: false,
        onClose: () => {
          this.dialog = undefined;
          events.emit("uiOut");

          /** Действие после завершения дочерней сцены: без гонки resume/restart. */
          parentScene.time.delayedCall(0, () => action?.());
        },
      },
    });
  }

  /** Удаляет активный диалог при уходе с экрана. */
  destroy() {
    this.unSubs.destroy();
  }
}
