import {
  makeView,
  UnSubManager,
  arrayAlign,
  makeAlign,
  type SceneEvents,
} from "@kvisaz/phaser-common";
import type { SolitaireId } from "../../../scenes";
import { consumableMagicButton, helpButton, iconButton } from "../../shared/buttons";
import { uiColors, uiFonts, uiTextStyle } from "../../shared/style";
import { ISolitairesSceneEvents } from "./events";

/** Разряды ходов и очков с ведущими нулями: наибольший счёт — 1300 (Сорок разбойников), ходов в партии — сотни. */
const statDigits = 4;

type StatKey = "time" | "moves" | "score";

/** Отступ правого края ряда статистики от правого края экрана, px. */
const statRightPx = 305;

/** Промежутки ряда статистики слева направо: подпись–число, число–точка, точка–подпись. */
const statGaps = { label: 12, separator: 24 };

/** Время партии: MM:SS, с часами — H:MM:SS. */
function formatTime(seconds: number): string {
  const two = (value: number) => String(value).padStart(2, "0");
  const hours = Math.floor(seconds / 3600);
  const clock = `${two(Math.floor(seconds / 60) % 60)}:${two(seconds % 60)}`;
  return hours > 0 ? `${hours}:${clock}` : clock;
}

/** Ширина числа под длину его формата: все цифры как нули, выравнивание влево. */
function reserveWidth(view: Phaser.GameObjects.Text, value: string): void {
  view.setFixedSize(0, 0).setText(value.replace(/\d/g, "0"));
  view.setFixedSize(view.width, 0);
}

interface ISolitaireHudProps {
  scene: Phaser.Scene;
  events: Phaser.Events.EventEmitter;
  t(key: string): string;
  gameId: SolitaireId;
  sceneEvents: SceneEvents<ISolitairesSceneEvents>;
  magicWandEnabled: boolean;
  isMagicRewardAvailable(): boolean;
  leftBarGap: number;
  leftBarLeft: number;
  leftBarTop: number;
}

/** Общая панель пяти игр: название, время, ходы, очки и кнопки из Classic XL. */
export class SolitaireHud {
  private readonly unSubs = new UnSubManager();
  /**
   * Числа статистики: ширина зарезервирована под длину формата, поэтому подписи «Время», «Ходы», «Очки» стоят на месте.
   * Ряд перестраивается только в ключевой точке — когда длина формата меняется, например у времени появились часы.
   */
  private readonly stats: Record<StatKey, Phaser.GameObjects.Text>;
  private readonly reservedLength: Record<StatKey, number> = { time: 0, moves: 0, score: 0 };
  private readonly statRow: Phaser.GameObjects.Text[];
  private readonly settings: Phaser.GameObjects.Image;
  readonly undo: Phaser.GameObjects.Image;
  readonly hint: Phaser.GameObjects.Image;
  readonly newGame: Phaser.GameObjects.Image;
  /** Кнопки нет, если игра не включает магическую палочку в своём конфиге. Число зарядов — setValueData. */
  readonly magic?: Phaser.GameObjects.Container;

  /**
   * Создаёт UI непосредственно в сцене, без родительского контейнера.
   * Кнопки не знают про экран: они эмитят команды `hud*` в SceneEvents, а обработку ведёт SolitaireView.
   */
  constructor(private readonly props: ISolitaireHudProps) {
    const {
      scene,
      events,
      t,
      gameId,
      sceneEvents,
      magicWandEnabled,
      isMagicRewardAvailable,
      leftBarGap,
      leftBarLeft,
      leftBarTop,
    } = props;
    const bg = makeView(scene, (b) => b.rect({ width: 1920, height: 128, color: uiColors.dark }));
    const title = makeView(scene, (b) =>
      b.text({
        text: t(gameId),
        style: {
          fontFamily: uiFonts.notoSerifBold.fontFamily,
          fontSize: 48,
          color: uiColors.cream,
        },
      }),
    );
    const help = helpButton({
      scene,
      events,
      text: t("help"),
      onClick: () => sceneEvents.emit("hudHelp"),
    });
    const home = iconButton({
      scene,
      events,
      name: "home",
      onClick: () => sceneEvents.emit("hudHome"),
    });
    const settings = (this.settings = iconButton({
      scene,
      events,
      name: "settings",
      onClick: () => sceneEvents.emit("hudSettings"),
    }));
    this.newGame = iconButton({
      scene,
      events,
      name: "newGame",
      onClick: () => sceneEvents.emit("hudNewGame"),
    });
    this.undo = iconButton({
      scene,
      events,
      name: "undo",
      onClick: () => sceneEvents.emit("hudUndo"),
    });
    this.hint = iconButton({
      scene,
      events,
      name: "hint",
      onClick: () => sceneEvents.emit("hudHint"),
    });
    this.magic = magicWandEnabled
      ? consumableMagicButton({
          scene,
          events,
          onClick: () => sceneEvents.emit("hudMagic"),
          isRewardModeEnabled: isMagicRewardAvailable,
        })
      : undefined;
    const text = (value: string) =>
      makeView(scene, (b) => b.text({ text: value, style: uiTextStyle(30, uiColors.cream) }));
    this.stats = { time: text(""), moves: text(""), score: text("") };
    const { time, moves, score } = this.stats;
    const statRow = (this.statRow = [
      text(t("time")),
      time,
      text("·"),
      text(t("moves")),
      moves,
      text("·"),
      text(t("score")),
      score,
    ]);
    const controls = [this.newGame, this.undo, this.hint, ...(this.magic ? [this.magic] : [])];
    makeAlign((a) => {
      a.anchorSceneScreen(scene).leftIn(bg).topIn(bg);
      a.leftIn(home, 0).topIn(home, 0);
      a.rightIn(settings, 0).topIn(settings, 7);
      a.leftIn(title, 176).topIn(title, 38);
      a.anchor(title).rightTo(help, 44).centerY(help, 4);
      a.column(controls, leftBarGap);
      a.anchorSceneScreen(scene)
        .leftIn(arrayAlign.alignObject(controls), leftBarLeft)
        .topIn(arrayAlign.alignObject(controls), leftBarTop);
    });
    this.unSubs.addUnSub([bg, title, help, home, settings, ...statRow, ...controls]);
    // Первый вызов резервирует ширины и ставит ряд статистики.
    this.update(0, 0);
  }

  /** Показывает время активной сцены, ходы движка и очки за базы; при смене длины формата перестраивает ряд. */
  update(seconds: number, moves: number, score = 0) {
    const values: Record<StatKey, string> = {
      time: formatTime(seconds),
      moves: String(moves).padStart(statDigits, "0"),
      score: String(score).padStart(statDigits, "0"),
    };
    let resized = false;
    (Object.keys(values) as StatKey[]).forEach((key) => {
      const value = values[key];
      if (value.length !== this.reservedLength[key]) {
        reserveWidth(this.stats[key], value);
        this.reservedLength[key] = value.length;
        resized = true;
      }
      this.stats[key].setText(value);
    });
    if (resized) this.layoutStats();
  }

  /** Ряд статистики справа налево от правого края экрана: числа — колонками своей ширины, подписи за ними. */
  private layoutStats() {
    const { statRow, settings } = this;
    const { time, moves, score } = this.stats;
    makeAlign((a) => {
      a.anchorSceneScreen(settings.scene).rightIn(score, -statRightPx);
      a.anchor(settings).centerY(score);
      for (let i = statRow.length - 2; i >= 0; i--) {
        const gap =
          statRow[i + 1] === time || statRow[i + 1] === moves || statRow[i + 1] === score
            ? statGaps.label
            : statGaps.separator;
        a.anchor(statRow[i + 1])
          .leftTo(statRow[i], -gap)
          .centerY(statRow[i]);
      }
    });
  }

  /** Удаляет все элементы панели. */
  destroy() {
    this.unSubs.destroy();
  }
}
