import {
  PreloadTask,
  UnSubManager,
  preloadAssets,
  setVpx,
  setupHtmlLoader,
} from "@kvisaz/phaser-common";
import { autoAssetsConfig } from "../../autoAssetsConfig";
import { SCENES } from "../../scenes";
import { services } from "../../services";
import { ensureCardFaceAtlas } from "../shared/CardView/CardView";

/** Загружает ресурсы и один раз готовит сервисы игры. */
export class BootScene extends Phaser.Scene {
  private readonly unSubs = new UnSubManager();

  /** Начальная сцена обычной игры, без настроек сторибука. */
  constructor() {
    super(SCENES.boot);
  }

  /** Добавляет подготовку SDK и сохранения в обычный Phaser loader. */
  preload(): void {
    setVpx(this.scale.width);
    this.unSubs.addUnSub(setupHtmlLoader({ scene: this, elementId: "loader" }));
    preloadAssets(this, {
      ...autoAssetsConfig.preload,
      images: autoAssetsConfig.preload.images.filter(({ name }) => !name.startsWith("background")),
    });
    PreloadTask.load(this, services.prepareGameServices());
  }

  /** Запускает зарегистрированную сцену сервисов, затем меню по ключу. */
  create(): void {
    this.unSubs.destroy();
    /** Шрифты и язык уже готовы: лица карт запекаем здесь, а не на старте первой партии. */
    ensureCardFaceAtlas(this, services.locale.t);
    services.yandexSdkWrapperV2.signalGameReady();

    /** Постоянные сервисы запускаются раньше игрового экрана. */
    this.scene.launch(SCENES.services);
    this.scene.start(SCENES.menu);
  }
}
