import { CardValueMap, type CardValue } from "@kvisaz/phaser-common";
import type { IBaseScorer, IScoreCard } from "../types";

interface ISpiderRunsScorerProps {
  /** восемь мастей K…A по 12 пар */
  maxBase?: number;
}

/** Достоинство для цепочек Паука: туз младший. */
function rank({ value }: IScoreCard): number {
  return value === "ace" ? 1 : CardValueMap[value as CardValue];
}

/** Пара соседних карт цепочки: обе открыты, одна масть, верхняя на единицу младше нижней. */
function isRunPair(lower: IScoreCard, upper: IScoreCard): boolean {
  return (
    lower.isFaceUp && upper.isFaceUp && lower.suit === upper.suit && rank(lower) === rank(upper) + 1
  );
}

/** Паук: одномастная цепочка длиной N даёт N − 1, то есть считается каждая правильная соседняя пара во всех стопках. */
export function spiderRunsScorer({ maxBase = 96 }: ISpiderRunsScorerProps = {}): IBaseScorer {
  return {
    maxBase,
    count: (stacks) =>
      [...stacks.values()].reduce(
        (sum, cards) =>
          sum + cards.filter((card, i) => i > 0 && isRunPair(cards[i - 1], card)).length,
        0,
      ),
  };
}
