interface IMagicChargesProps {
  /** бесплатные заряды этой партии: тратятся первыми и не сохраняются */
  free: number;
  /** заряды, полученные за рекламу, из сохранения */
  paid: number;
  /** сохранить оставшиеся купленные заряды */
  savePaid: (paid: number) => void;
  /** число зарядов изменилось — обновить кнопку */
  onChange: (count: number) => void;
}

/** Заряды Magic в партии: сначала бесплатный заряд партии, потом полученные за рекламу. */
export class MagicCharges {
  private free: number;
  private paid: number;

  constructor(private readonly props: IMagicChargesProps) {
    this.free = props.free;
    this.paid = props.paid;
    props.onChange(this.count);
  }

  get count(): number {
    return this.free + this.paid;
  }

  /** Тратит заряд; false — зарядов нет. */
  spend(): boolean {
    if (this.free > 0) this.free--;
    else if (this.paid > 0) this.props.savePaid(--this.paid);
    else return false;
    this.props.onChange(this.count);
    return true;
  }

  /** Награда за рекламу: заряды добавляются и сразу сохраняются. */
  add(charges: number): void {
    this.paid += charges;
    this.props.savePaid(this.paid);
    this.props.onChange(this.count);
  }
}
