import { UnSubManager } from "@kvisaz/phaser-common";

/** Настройки наклона и веса: стартовые значения мануала, подбираются на глаз. */
const motionConfig = {
  meshFov: 45,
  maxTiltDeg: 10,
  /** градусов наклона на 1 px/с скорости карты */
  tiltPerSpeed: 0.012,
  /** крен в плоскости экрана: карта «висит» и отстаёт за движением */
  leanPerSpeed: 0.006,
  maxLeanDeg: 6,
  /** вес: пружина картинки — жёсткость, затухание и разброс жёсткости между картами */
  springOmega: 32,
  springDamping: 0.82,
  springOmegaSpread: 0.15,
  /** скорость сглаживания наклона и подъёма, 1/с */
  smoothing: 18,
  maxDeltaMs: 50,
  /** состояние указателя в InputPlugin: идёт перетаскивание */
  pointerDragging: 4,
  hoverLift: 1,
  dragLift: 1.6,
  liftScale: 0.06,
  liftRise: 6,
  /** ниже этих значений карта считается успокоившейся */
  restTiltDeg: 0.3,
  restLift: 0.02,
  restOffset: 0.5,
  restSpeed: 5,
} as const;

/** Состояние пружины одной координаты. */
interface ISpring {
  value: number;
  velocity: number;
}

interface ICardMotion3DProps {
  scene: Phaser.Scene;
  card: Phaser.GameObjects.Container & { readonly isFaceUp: boolean };
  textureKey: string;
  frame: string;
  width: number;
  height: number;

  /** Плоское лицо: прячется на время наклона и возвращается, когда карта успокоилась. */
  hideFlatFace(): void;

  showFlatFace(): void;
}

/**
 * Наклон, подъём и вес карты. Движет только свой Mesh: сама карта, её ввод и границы не меняются.
 * Класс, а не data карты: состояние пишется каждый кадр у каждой карты и включает Mesh и подписки.
 */
export class CardMotion3D {
  private readonly unSubs = new UnSubManager();
  private readonly mesh: Phaser.GameObjects.Mesh;
  private hovered = false;
  private dragged = false;
  private lift = 0;
  private lastX = 0;
  private lastY = 0;
  private readonly springX: ISpring = { value: 0, velocity: 0 };
  private readonly springY: ISpring = { value: 0, velocity: 0 };
  /** Своя жёсткость у каждой карты: пачка движется не как один кусок. */
  private readonly springOmega =
    motionConfig.springOmega *
    Phaser.Math.FloatBetween(
      1 - motionConfig.springOmegaSpread,
      1 + motionConfig.springOmegaSpread,
    );

  constructor(private readonly props: ICardMotion3DProps) {
    const { scene, card } = props;

    /** Заранее: Mesh считает вершины только со следующего кадра, созданный при наведении мигнул бы пустым. */
    this.mesh = createMotionMesh(props);

    const onPointerOver = (pointer: Phaser.Input.Pointer) => {
      this.hovered = !pointer.wasTouch;
    };
    const onPointerOut = () => {
      this.hovered = false;
    };
    card.on(Phaser.Input.Events.GAMEOBJECT_POINTER_OVER, onPointerOver);
    card.on(Phaser.Input.Events.GAMEOBJECT_POINTER_OUT, onPointerOut);

    /** Покадрово: пружина догоняет карту, а движение пачки видно только по самой карте. После всех записей x/y за кадр. */
    scene.events.on(Phaser.Scenes.Events.POST_UPDATE, this.update, this);

    this.unSubs.addUnSub(() => {
      card.off(Phaser.Input.Events.GAMEOBJECT_POINTER_OVER, onPointerOver);
      card.off(Phaser.Input.Events.GAMEOBJECT_POINTER_OUT, onPointerOut);
      scene.events.off(Phaser.Scenes.Events.POST_UPDATE, this.update, this);
    });
  }

  /** Снимает подписки; Mesh уничтожается вместе с детьми карты. */
  destroy() {
    this.unSubs.destroy();
  }

  /** Прячет Mesh: карта вызывает это при любой смене стороны, Mesh показывает только лицо. */
  hideMesh() {
    this.mesh.setVisible(false);
  }

  /** Наведение наклоняет карту к указателю; при движении картинка отстаёт на пружине и кренится по её скорости. */
  private update(_time: number, delta: number) {
    const { mesh, lastX, lastY } = this;
    const { scene, card, width, height, showFlatFace } = this.props;
    const { x, y, scaleY } = card;
    this.lastX = x;
    this.lastY = y;

    /** Ввод партия включает после раздачи: до этого карта не реагирует. */
    if (card.input == null) return;

    const { input } = scene;
    const pointer = input.activePointer;
    const moved = x !== lastX || y !== lastY;
    /** Только настоящий жест: карты, летящие по кнопке или ходу, под него не попадают. */
    this.dragged =
      input.getDragState(pointer) === motionConfig.pointerDragging && (this.dragged || moved);

    /** Карта может уехать из-под неподвижного указателя, а pointerout придёт только при его движении. */
    const pointerX = (pointer.worldX - x) / ((width * scaleY) / 2);
    const pointerY = (pointer.worldY - y) / ((height * scaleY) / 2);
    const hovered = this.hovered && Math.abs(pointerX) <= 1 && Math.abs(pointerY) <= 1;
    const active = card.isFaceUp && (this.dragged || hovered);
    if (!active && !mesh.visible) return;

    this.showMesh();

    const { springX, springY, springOmega } = this;
    const seconds = Phaser.Math.Clamp(delta, 1, motionConfig.maxDeltaMs) / 1000;
    stepSpring(springX, x, seconds, springOmega);
    stepSpring(springY, y, seconds, springOmega);

    const { maxTiltDeg, tiltPerSpeed, leanPerSpeed, maxLeanDeg } = motionConfig;
    const useHoverTilt = hovered && !this.dragged && !pointer.isDown;
    const targetX = useHoverTilt
      ? -pointerY * maxTiltDeg
      : Phaser.Math.Clamp(-springY.velocity * tiltPerSpeed, -maxTiltDeg, maxTiltDeg);
    const targetY = useHoverTilt
      ? pointerX * maxTiltDeg
      : Phaser.Math.Clamp(springX.velocity * tiltPerSpeed, -maxTiltDeg, maxTiltDeg);
    const targetLean = Phaser.Math.Clamp(-springX.velocity * leanPerSpeed, -maxLeanDeg, maxLeanDeg);
    const targetLift = !active ? 0 : this.dragged ? motionConfig.dragLift : motionConfig.hoverLift;

    const blend = 1 - Math.exp(-motionConfig.smoothing * seconds);
    const { modelRotation } = mesh;
    modelRotation.x += (Phaser.Math.DegToRad(targetX) - modelRotation.x) * blend;
    modelRotation.y += (Phaser.Math.DegToRad(targetY) - modelRotation.y) * blend;
    mesh.angle += (targetLean - mesh.angle) * blend;
    this.lift += (targetLift - this.lift) * blend;

    mesh.setScale(1 + this.lift * motionConfig.liftScale);
    mesh.x = (springX.value - x) / scaleY;
    mesh.y = (springY.value - y) / scaleY - this.lift * motionConfig.liftRise;

    const restTilt = Phaser.Math.DegToRad(motionConfig.restTiltDeg);
    const settled =
      Math.abs(modelRotation.x) < restTilt &&
      Math.abs(modelRotation.y) < restTilt &&
      this.lift < motionConfig.restLift &&
      Math.abs(springX.value - x) < motionConfig.restOffset &&
      Math.abs(springY.value - y) < motionConfig.restOffset &&
      Math.abs(springX.velocity) < motionConfig.restSpeed &&
      Math.abs(springY.velocity) < motionConfig.restSpeed;
    if (!active && settled) showFlatFace();
  }

  /** Подменяет плоское лицо наклоняемым и ставит пружину на текущее место карты. */
  private showMesh() {
    const { mesh, springX, springY } = this;
    if (mesh.visible) return;

    const { card, hideFlatFace } = this.props;
    springX.value = card.x;
    springY.value = card.y;
    springX.velocity = 0;
    springY.velocity = 0;

    mesh.modelRotation.set(0, 0, 0);
    mesh.angle = 0;
    this.lift = 0;
    mesh.setVisible(true);
    hideFlatFace();
  }
}

/**
 * Сетка 4 × 6 в масштабе 1:1 с картой: так перспектива не заметна на изломах текстуры.
 *
 * Mesh можно свободно двигать и масштабировать: на границы карты он не влияет. У него нет `getBounds`,
 * а `Container.getBounds` объединяет только детей с этим методом, поэтому раскладка и выбор стопки
 * при броске его не видят. С `Image` или `Text` так нельзя: их границы войдут в границы карты.
 */
function createMotionMesh(props: ICardMotion3DProps): Phaser.GameObjects.Mesh {
  const { scene, card, textureKey, frame, width, height } = props;
  const { meshFov } = motionConfig;
  const mesh = scene.add.mesh(0, 0, textureKey, frame).setVisible(false);

  mesh.setSize(width, height);
  mesh.setPerspective(width, height, meshFov, 0.01, 100);
  mesh.panZ(1 / Math.tan(Phaser.Math.DegToRad(meshFov) / 2));
  Phaser.Geom.Mesh.GenerateGridVerts({
    mesh,
    texture: textureKey,
    frame,
    width: width / height,
    height: 1,
    widthSegments: 4,
    heightSegments: 6,
  });
  mesh.hideCCW = false;

  card.add(mesh);
  return mesh;
}

/** Точное решение затухающей пружины на шаге при постоянной цели: не зависит от частоты кадров. */
function stepSpring(spring: ISpring, target: number, seconds: number, omega: number) {
  const { springDamping: damping } = motionConfig;
  const offset = spring.value - target;
  const a = damping * omega;
  const b = omega * Math.sqrt(1 - damping * damping);
  const decay = Math.exp(-a * seconds);
  const cos = Math.cos(b * seconds);
  const sin = Math.sin(b * seconds);
  const { velocity } = spring;

  spring.value = target + decay * (offset * cos + ((velocity + a * offset) * sin) / b);
  spring.velocity = decay * (velocity * cos - ((a * velocity + omega * omega * offset) * sin) / b);
}
