import { makeAlign, makeView } from "@kvisaz/phaser-common";
import { uiColors, uiFonts } from "../../../style";
import type { DialogButton } from "../../types";
import { getImageAsset } from "../../../../../assets";
import { dialogTitleStyle } from "../../config";

interface IDialogTitleProps {
  scene: Phaser.Scene;
  title: string;
  /** ширина рамки окна: полоса шапки уже неё на inset */
  width: number;
  /** крестик, созданный вызывающим; без него крестика нет */
  closeButton?: DialogButton;
}

/** Шапка окна: тёмная полоса, заголовок и крестик. Положение в окне задаёт DialogShell. */
export class DialogTitle extends Phaser.GameObjects.Container {
  constructor(private props: IDialogTitleProps) {
    super(props.scene, 0, 0);
    const { scene, title, width, closeButton } = this.props;
    const { height, titleLeft, fontSize } = dialogTitleStyle;

    const bg = makeView(scene, (b) =>
      b.nine({ ...getImageAsset("windowHeaderNine"), width, height, padding: 16 }),
    );

    // const bg = makeView(scene, b => b.rect({ width: width - inset, height, color: uiColors.dark }));
    const caption = makeView(scene, (b) =>
      b.text({
        text: title,
        style: { fontFamily: uiFonts.notoSerifBold.fontFamily, fontSize, color: uiColors.cream },
      }),
    );

    makeAlign((a) => {
      a.anchor(bg).leftIn(caption, titleLeft).centerY(caption);
      if (closeButton) a.rightIn(closeButton, 0).centerY(closeButton);
    });

    this.add([bg, caption, ...(closeButton ? [closeButton] : [])]);
  }
}
