import { onSceneShutdown, SafeEventsAdapter, UnSubManager } from "@kvisaz/phaser-common";
import { SCENES } from "../../scenes";
import { services } from "../../services";
import { MenuView } from "./MenuView/MenuView";
import type { IMenuEvents } from "./events";

/** Меню собирает только свой интерфейс. Общие сервисы не принадлежат экрану. */
export class MenuScene extends Phaser.Scene {
  private readonly unSubs = new UnSubManager();

  /** Регистрирует сцену меню. */
  constructor() {
    super(SCENES.menu);
  }

  /** Создаёт меню и открывает выбранный пасьянс по событию. */
  create(): void {
    const { gameEvents, locale, playerDataService, leaderboardService } = services;
    const scene = this;
    const { t, lang } = locale;

    /** Адаптер хранит подписки только этого запуска сцены. */
    const events = new SafeEventsAdapter<IMenuEvents>(gameEvents);
    this.unSubs.addUnSub(() => events.unSubscribeAll());

    /** Выбор игры закрывает меню и запускает сцену партии. */
    events.on("requestGameScreen", ({ gameId }) => {
      this.scene.start(SCENES.solitaire, { gameId });
    });

    /** Меню получает только нужные ему данные и действия. */
    this.unSubs.addUnSub(
      new MenuView({
        scene,
        events: gameEvents,
        t,
        isTableWithPlayer: (board) => leaderboardService.isTableWithPlayer(board),
        loadLeaderboard: (board) => leaderboardService.getEntries(board),
        isWinAnimationAllowed: () => playerDataService.getData().isWinAnimationAllowed,
        onWinAnimationAllowedChange: (value) => {
          void playerDataService.patch(() => ({ isWinAnimationAllowed: value })).flush();
        },
      }),
    );

    /** При уходе удаляем View и обработчик выбора игры. */
    this.unSubs.addUnSub(onSceneShutdown(scene, () => this.unSubs.destroy()));

    /** Название вкладки и язык страницы соответствуют выбранной локали. */
    document.title = t("title");
    document.documentElement.lang = lang;
  }
}
