import { makeView } from "@kvisaz/phaser-common";
import { uiTextStyle } from "../../style";
import { leaderboardConfig } from "../config";

interface ILeaderboardRowDividerProps {
  scene: Phaser.Scene;
}

/** Разделитель «…» между строками рейтинга, где места идут не подряд. */
export class LeaderboardRowDivider extends Phaser.GameObjects.Container {
  constructor(private props: ILeaderboardRowDividerProps) {
    super(props.scene, 0, 0);
    const { scene } = this.props;
    this.add(
      makeView(scene, (b) => b.text({ text: "…", style: uiTextStyle(leaderboardConfig.fontSize) })),
    );
  }
}
