import { fitToSize } from "@kvisaz/phaser-common";
import { getImageAsset } from "../../../../assets";

interface ILeaderboardSpinnerProps {
  scene: Phaser.Scene;
}

/** Индикатор загрузки рейтинга: cardsFlower крутится, пока таблица не пришла. */
export class LeaderboardSpinner extends Phaser.GameObjects.Image {
  private readonly tween: Phaser.Tweens.Tween;

  constructor(private props: ILeaderboardSpinnerProps) {
    const { textureName, frameName } = getImageAsset("cardsFlower");
    super(props.scene, 0, 0, textureName, frameName);
    const { scene } = this.props;
    fitToSize({ gameObject: this, width: 160, height: 160 });
    this.tween = scene.tweens.add({ targets: this, angle: 360, duration: 1200, repeat: -1 });
  }

  destroy(fromScene?: boolean) {
    this.tween.remove();
    super.destroy(fromScene);
  }
}
