import {
  arrayAlign,
  cardEngineV1,
  createSimpleCardData,
  makeView,
  makeAlign,
  UnSubManager,
  type ICardPlace,
  type IClassicCardDto,
  type Observable,
} from "@kvisaz/phaser-common";
import { placeView, stackLayout, tableLayout } from "../solitaires/tableLayout";
import type { SolitaireId } from "../../../scenes";
import { CardView, CARD_HEIGHT, CARD_WIDTH } from "../../shared/CardView/CardView";
import { variants } from "../solitaires/variants";
import { uiTextStyle } from "../../shared/style";
import type { ISolitaireConfig } from "../solitaires/types";

/** Общее состояние пяти готовых партий библиотеки: экран читает только эти поля. */
export interface ISolitaireCoreState {
  readonly step: cardEngineV1.EngineStep;
  readonly action?: string;
  readonly historyLength: number;
  /** Подсказка — лучший полезный ход; её может не быть и при ходах. */
  readonly hint?: unknown;
  /** Тупик партии: считает библиотека. */
  readonly deadEnd?: "noMoves" | "uselessMoves";
  /** Нет магии — кнопка палочки тускнеет. */
  readonly magic?: unknown;
  /** Партия решена: показывать кнопку «Собрать». */
  readonly autoCollect: boolean;
  readonly won: boolean;
}

/** Общее у пяти готовых партий: KlondikeCoreGame, SpiderCoreGame и остальные подходят без обёрток. */
export interface ISolitaireCore {
  readonly state: Observable<Readonly<ISolitaireCoreState>>;
  start(): void;
  undo(): Promise<void>;
  showHint(): Promise<void>;
  /** Ход по подсказке, как клик игрока: автоигра витрины для промо-видео. */
  playHint(): Promise<void>;
  magic(): Promise<void>;
  /** Автосбор: все карты на базы, весь сбор — одно Undo. */
  autoCollect(): Promise<void>;
  /** Запас: есть у Косынки, Паука и 40 разбойников. */
  dealStock?(): Promise<void>;
  /** Стопки партии по роли места: базы — для победного танца. */
  getStacks(type?: string): cardEngineV1.IDragDropCardStack[];
  destroy(): void;
}

interface ISolitaireRoundProps {
  scene: Phaser.Scene;
  t(key: string): string;
  gameId: SolitaireId;
  deck?: readonly IClassicCardDto[];
}

/** Одна партия: плоское поле и готовая партия библиотеки, никаких корневых контейнеров. */
export class SolitaireRound {
  private readonly unSubs = new UnSubManager();
  readonly config: ISolitaireConfig;
  readonly core: ISolitaireCore;
  readonly cards: CardView[];
  readonly stock?: ICardPlace;

  /** Раскладывает места и передаёт их готовой партии выбранной игры; раздачу запускает экран через core.start(). */
  constructor(private readonly props: ISolitaireRoundProps) {
    const { scene, t, gameId, deck } = props;
    const spec = variants[gameId];
    this.config = spec.config;
    const { config } = this;
    const scale = config.cardScale;
    this.cards = (
      deck ?? createSimpleCardData({ copies: config.deckCopies, suits: config.deckSuits })
    ).map((dto, i) => new CardView({ scene, t, ...dto, id: `card-${i}` }).setScale(scale));
    // Сначала останавливаем анимации и ввод партии, только затем удаляем места. Карты уничтожает партия.
    this.unSubs.addUnSub(() => this.core.destroy());
    /** Место имеет те же полные границы, что PNG карты, включая прозрачный край тени. */
    const place = (type: string) => {
      const view = placeView({
        scene,
        type,
        width: CARD_WIDTH * scale,
        height: CARD_HEIGHT * scale,
      });
      this.unSubs.addUnSub(view);
      return view;
    };

    const stock = (this.stock = config.stockMode !== "none" ? place("stock") : undefined);
    const waste =
      config.stockMode === "once" || config.stockMode === "recycle" ? place("waste") : undefined;

    const cells = Array.from({ length: config.cellCount }, () => place("cell"));
    const bases = Array.from({ length: config.baseCount }, () => place("base"));
    const tables = Array.from({ length: config.tableColumns }, () => place("table"));
    spec.layout(scene, { tables, cells, bases, stock, waste }, config);

    // Базы отличаются от свободных ячеек, но не закреплены за конкретной мастью.
    bases.forEach((base) => {
      const label = makeView(scene, (b) =>
        b.text({
          text: t(config.baseStartValue === "king" ? "rank_king" : "rank_ace"),
          style: uiTextStyle(config.baseLabelSize * scale, "#739583"),
        }),
      ).setDepth(-1);
      makeAlign((a) => a.anchor(base).center(label));
      this.unSubs.addUnSub(label);
    });

    /** Роли мест для партии: колонки — адаптивная раскладка игры, остальное — плотная стопка. */
    const table = tableLayout(config, scene.scale.height - config.tableBottomMargin);
    const tablePlaces = tables.map((cardPlace) => ({ cardPlace, layout: table }));
    const stack = (cardPlace: ICardPlace) => ({ cardPlace, layout: stackLayout });
    /** Юкону и FreeCell колода нужна только для раздачи: под колонками по центру ряда, у нижнего края — карты летят вверх в пустые колонки. */
    const startDeal = () => {
      const zone = scene.add.zone(0, 0, CARD_WIDTH * scale, CARD_HEIGHT * scale);
      makeAlign((a) => {
        a.anchor(arrayAlign.alignObject(tables)).centerX(zone);
        a.anchorSceneScreen(scene).bottomIn(zone, -config.tableBottomMargin);
      });
      this.unSubs.addUnSub(zone);
      return stack(zone);
    };

    const coreProps = {
      scene,
      cards: this.cards,
      timings: {
        moveDurationMs: config.moveDuration,
        flipDurationMs: config.flipDuration,
        dealDurationMs: config.dealMoveDuration,
        dealFlipDurationMs: config.dealFlipDuration,
        /** движок сливает тайминги через spread: undefined затёр бы шаг игры, поэтому ключ — только если задан */
        ...(config.dealInterval === undefined ? {} : { dealIntervalMs: config.dealInterval }),
      },
    };
    const {
      KlondikeCoreGame,
      SpiderCoreGame,
      FreeCellCoreGame,
      YukonCoreGame,
      FortyThievesCoreGame,
    } = cardEngineV1;
    /** Одна запись на игру: создание партии. Забытая игра — ошибка типа.
     * Партия создаётся лениво, поэтому колода и сброс читаются только там, где они есть. */
    const cores = {
      klondike: {
        create: () =>
          new KlondikeCoreGame({
            ...coreProps,
            cardPlaces: {
              deck: stack(stock!),
              deckGrave: stack(waste!),
              tables: tablePlaces,
              bases: bases.map(stack),
            },
          }),
      },
      spider: {
        create: () =>
          new SpiderCoreGame({
            ...coreProps,
            cardPlaces: { deck: stack(stock!), tables: tablePlaces, bases: bases.map(stack) },
          }),
      },
      freecell: {
        create: () =>
          new FreeCellCoreGame({
            ...coreProps,
            cardPlaces: {
              tables: tablePlaces,
              cells: cells.map(stack),
              bases: bases.map(stack),
              startDeal: startDeal(),
            },
          }),
      },
      yukon: {
        create: () =>
          new YukonCoreGame({
            ...coreProps,
            cardPlaces: { tables: tablePlaces, bases: bases.map(stack), startDeal: startDeal() },
          }),
      },
      fortyThieves: {
        create: () =>
          new FortyThievesCoreGame({
            ...coreProps,
            cardPlaces: {
              deck: stack(stock!),
              deckGrave: stack(waste!),
              tables: tablePlaces,
              bases: bases.map(stack),
            },
          }),
      },
    } satisfies Record<SolitaireId, { create: () => ISolitaireCore }>;
    this.core = cores[gameId].create();
  }

  /** Отменяет жесты/твины перед удалением карт и мест. */
  destroy() {
    this.unSubs.destroy();
  }
}
