import { HtmlRoot, setupBrowser } from "@kvisaz/phaser-common";
import { phaserGameConfig } from "./configs/config";
import { BootScene } from "./scenes/Boot/BootScene";
import { ServicesScene } from "./scenes/ServicesScene";
import { MenuScene } from "./scenes/Menu/MenuScene";
import { SolitaireScene } from "./scenes/Solitaire/SolitaireScene";
import { DemoScene } from "./scenes/Demo/DemoScene";

/** Запускает обычный Phaser: собственные сцены и общие сервисы вместо GameCoreRuntime. */
export function startGame(): Phaser.Game {
  const root = document.getElementById("game")!;
  HtmlRoot.root = root;
  const game = new Phaser.Game({
    ...phaserGameConfig,
    parent: root,
    scale: { ...phaserGameConfig.scale, parent: root },
    scene: [BootScene, ServicesScene, MenuScene, SolitaireScene, DemoScene],
  });
  setupBrowser({ game, disableContextMenu: true, iosAudioResumePatch: true });
  return game;
}
