import {
  fitToSize,
  makeAlign,
  makeView,
  SwitchButton,
  SafeEventsAdapter,
} from "@kvisaz/phaser-common";
import { getImageAsset } from "../../assets";
import { uiColors, uiTextStyle } from "./style";
import type { IUiEvents } from "./events";

interface IToggleProps {
  scene: Phaser.Scene;
  events: Phaser.Events.EventEmitter;
  t(key: string): string;
}

/**
 * Переключатель 0.8 от PNG 256×128: готовые PNG и состояние библиотечного SwitchButton.
 * На свободной половине — «Вкл» слева от бегунка или «Выкл» справа; тексты из локали.
 */
export function toggle(context: IToggleProps, isOn: boolean, onChange: (value: boolean) => void) {
  const { scene, t } = context;
  const events = new SafeEventsAdapter<IUiEvents>(context.events);
  const view = (on: boolean) =>
    makeView(scene, (b) => {
      const bg = b.img(getImageAsset(on ? "toggleOn" : "toggleOff"));
      const label = b.text({
        text: t(on ? "toggle_on" : "toggle_off"),
        style: uiTextStyle(32, on ? uiColors.cream : uiColors.ink),
      });
      // Подпись по центру свободной половины: бегунок у «Вкл» справа, у «Выкл» слева.
      const half = bg.displayWidth / 2;
      makeAlign((a) => {
        a.anchor(bg).centerY(label);
        if (on) a.leftIn(label, (half - label.width) / 2);
        else a.rightIn(label, -(half - label.width) / 2);
      });
      const content = b.con([bg, label]);
      // Три строки настроек помещаются над кнопкой окна только у уменьшенного переключателя.
      fitToSize({ gameObject: content, width: bg.width * 0.8, height: bg.height * 0.8 });
      return content;
    });
  const viewOn = view(true);
  const viewOff = view(false);
  return new SwitchButton({
    viewOn,
    viewOff,
    isOn,
    // У ContainerButton библиотеки по умолчанию once: true — переключатель сработал бы только один раз.
    options: { once: false },
    onSwitchClick: (value) => {
      events.emit("uiToggle", value);
      onChange(value);
    },
    onOver: () => events.emit("uiHover"),
    onOut: () => events.emit("uiOut"),
  });
}
