import { arrayAlign, makeAlign } from "@kvisaz/phaser-common";
import type { SolitaireLayout } from "../types";

/**
 * Свободная ячейка: сверху четыре ячейки и четыре базы с пустотой между группами.
 * Восемь колонок идут тем же шагом, поэтому уже верхнего ряда и прижаты к его правому краю, под базами.
 * Всё поле прижато к правому краю экрана с отступом rightMarginX. Шаг и верх карт — из конфига, остальное — в начале функции.
 */
export const layoutFreecell: SolitaireLayout = (scene, { tables, cells, bases }, config) => {
  /** Пустота между ячейками и базами, px. */
  const groupsGap = 120;
  /** Отступ правого края поля от края экрана, px. */
  const rightMarginX = 38;
  const { cardsTopY, placeGap } = config;
  const tableTopY = cardsTopY + cells[0].getBounds().height + placeGap;
  makeAlign((a) => {
    a.row(cells, placeGap);
    a.row(bases, placeGap);
    const cellRow = arrayAlign.alignObject(cells);
    a.anchor(arrayAlign.alignObject(bases)).leftTo(cellRow, -groupsGap);
    const upperRow = arrayAlign.alignObject([...cells, ...bases]);
    a.anchorSceneScreen(scene).topIn(upperRow, cardsTopY);
    a.row(tables, placeGap);
    const tableRow = arrayAlign.alignObject(tables);
    a.anchor(arrayAlign.alignObject([...cells, ...bases])).rightIn(tableRow);
    a.anchorSceneScreen(scene).topIn(tableRow, tableTopY);

    const allCards = arrayAlign.alignObject([...cells, ...bases, ...tables]);
    a.anchorSceneScreen(scene).rightIn(allCards, -rightMarginX);
  });
  // Шаг у ячеек и колонок один, поэтому, выровняв последнюю ячейку по третьей колонке, мы выравниваем все.
  const dx = tables[2].getBounds().left - cells[cells.length - 1].getBounds().left;
  cells.forEach((cell) => {
    cell.x += dx;
  });
};
