import {
  arrayAlign,
  cardEngineV1,
  cssColorToInt,
  Explosions,
  HtmlBackground,
  type ICardPlace,
  type IClassicCardDto,
  type IExplodeParticlesProps,
  makeButton,
  SafeEventsAdapter,
  SceneEvents,
  setValueData,
  UnSubManager
} from "@kvisaz/phaser-common";
import type { SolitaireId } from "../../../scenes";
import { autoAssetsConfig } from "../../../autoAssetsConfig";
import { Dialogs } from "../../shared/dialog/Dialogs";
import {
  layoutAutoCollectButton,
  makeAutoCollectButton,
  startAutoCollectCta
} from "../../shared/AutoCollectButton/makeAutoCollectButton";
import { type ISolitaireCoreState, SolitaireRound } from "./SolitaireRound";
import { SolitaireHud } from "./SolitaireHud";
import { MagicCharges } from "./MagicCharges";
import { WinDance } from "./components/WinDance/WinDance";
import { SolitaireScoreLogic } from "../SolitaireScoreLogic";
import { variants } from "../solitaires/variants";
import { DialogKind } from "../../shared/dialog/types";
import { HelpView } from "./components/HelpView/HelpView";
import type { ISolitaireEvents, ISolitairesSceneEvents } from "./events";

/** Куда уходит игрок после рекламной паузы: меню, новая партия или просто пауза после оборота колоды. */
type AdNext = SolitaireId | "menu" | "recycle";

/** Конфетти на базу: мелкие золотые звёзды, живут меньше узора библиотеки. */
const baseConfettiStyle = {
  count: 15,
  size: { start: 12, end: 24 },
  /** разлёт = скорость × время: жизнь вдвое короче узора, скорость 0.7 от узорной (500–950) */
  lifespan: { min: 450, max: 750 },
  speed: { min: 350, max: 665 },
  shape: "star",
  colors: ["#d6a143"].map(cssColorToInt),
  /** оборотов на частицу вдвое меньше: темп вращения остаётся прежним при вдвое более короткой жизни */
  rotate: { start: 0, end: 90 }
} satisfies Partial<IExplodeParticlesProps>;

interface ISolitaireViewProps {
  scene: Phaser.Scene;
  events: Phaser.Events.EventEmitter;

  t(key: string): string;

  gameId: SolitaireId;
  magicCharges: number;

  saveMagicCharges(value: number): void;

  isWinAnimationAllowed(): boolean;

  onWinAnimationAllowedChange(value: boolean): void;

  isRewardedAvailable(): boolean;

  deck?: readonly IClassicCardDto[];
}

/** Общий экран: связывает готовую партию библиотеки, UI и диалоги; сам не содержит правил. */
export class SolitaireView {
  private readonly unSubs = new UnSubManager();
  readonly round: SolitaireRound;
  /** Очки сеанса: витрина открывает по ним итог, не доигрывая партию. */
  readonly score: SolitaireScoreLogic;

  /** Локальные подписки не затрагивают обработчики сервисов и других компонентов. */
  private readonly events: SafeEventsAdapter<ISolitaireEvents>;
  private readonly sceneEvents: SceneEvents<ISolitairesSceneEvents>;
  /** Факты партии и касания движка: имена едины для всех пяти игр. */
  private readonly coreEvents: SceneEvents<
    cardEngineV1.ISolitaireGameEvents & cardEngineV1.ICardDragDropEngineEvents
  >;
  private readonly dialogs: Dialogs;
  private readonly hud: SolitaireHud;
  private readonly charges: MagicCharges;

  /** Секунды сеанса: считает таймер экрана, модуль очков получает их через updateData. */
  private seconds = 0;
  /** Ходы сеанса для бонуса: каждый ход и каждая отмена, Undo счётчик не уменьшает. */
  private moves = 0;
  /** Очки за базы: приходят из модуля очков. */
  private baseScore = 0;
  /** Время стартует только после первого хода игрока: клика по карте, по колоде или перетаскивания. */
  private started = false;
  /** false после destroy: поздние события рекламы ничего не делают. */
  private active = true;
  private pendingAd?: AdNext;
  private recycleAdPending = false;
  private magicAdRequests = 0;
  private pendingMagicReward?: string;
  /** Кнопка «Собрать»: уничтожается кликом, после Undo создаётся заново. */
  private collect?: Phaser.GameObjects.Container;
  /** Сбор идёт: движок публикует IDLE между картами, и без флага кнопка создавалась бы заново после каждой. */
  private collecting = false;

  /** Запускает выбранный пасьянс; заданная колода позволяет воспроизводить раздачу в сториз. */
  constructor(private readonly props: ISolitaireViewProps) {
    const { scene, t, gameId, deck, magicCharges, saveMagicCharges, isRewardedAvailable } = props;

    this.events = new SafeEventsAdapter<ISolitaireEvents>(props.events);
    this.unSubs.addUnSub(() => this.events.unSubscribeAll());
    this.unSubs.addUnSub(() => {
      this.active = false;
      this.pendingAd = undefined;
    });
    this.unSubs.addUnSub(() => this.removeCollect());

    const background = new HtmlBackground({ url: autoAssetsConfig.images.backgroundCloth.url });
    const round = (this.round = new SolitaireRound({ scene, t, gameId, deck }));
    const { config } = round;
    this.dialogs = new Dialogs({
      scene,
      events: props.events,
      t,
      isWinAnimationAllowed: props.isWinAnimationAllowed,
      onWinAnimationAllowedChange: props.onWinAnimationAllowedChange
    });
    this.sceneEvents = new SceneEvents<ISolitairesSceneEvents>({ scene });
    this.coreEvents = new SceneEvents<
      cardEngineV1.ISolitaireGameEvents & cardEngineV1.ICardDragDropEngineEvents
    >({ scene });
    this.hud = new SolitaireHud({
      scene,
      events: props.events,
      t,
      gameId,
      sceneEvents: this.sceneEvents,
      magicWandEnabled: config.magicWandEnabled,
      isMagicRewardAvailable: isRewardedAvailable,
      leftBarGap: config.layoutLeftBarGapPx,
      leftBarLeft: config.layoutLeftBarLeftPx,
      leftBarTop: config.layoutLeftBarTopPx
    });
    this.score = new SolitaireScoreLogic({
      scorer: variants[gameId].scorer,
      limits: config.scoreLimits,
      bonusShare: config.bonusShare,
      scoreMax: config.scoreMax,
      onScoreChange: (next) => {
        this.baseScore = next;
        this.hud.update(this.seconds, round.core.state.getState().historyLength, next);
      }
    });
    /** Заряды Magic: бесплатный на партию, остальные — за рекламу; число — в бейдже кнопки, при нуле — значок рекламы. */
    this.charges = new MagicCharges({
      free: config.magicFreePerGame,
      paid: magicCharges,
      savePaid: saveMagicCharges,
      onChange: (count) => this.setMagicBadge(count)
    });

    this.unSubs.addUnSub([
      () => this.sceneEvents.unSubscribeAll(),
      () => this.coreEvents.unSubscribeAll(),
      this.dialogs,
      round,
      this.hud,
      background
    ]);

    this.initAds();
    this.initMagicReward();
    this.initTimer();
    this.initHudCommands();
    this.initStockButton();
    this.initDealSounds();
    this.initMoves();
    this.initCoreState();
    this.initUndoCount();
    this.initWin();
    this.initDeadEnd();
    this.initRecycleAd();

    // start() сразу публикует состояние раздачи — подписка выше сама выставит кнопки.
    round.core.start();
  }

  /** Отписывает UI, останавливает партию и удаляет все объекты экрана. */
  destroy(): void {
    this.unSubs.destroy();
  }

  /** Пауза рекламы запрашивается событием; переход выполняется только на continue. */
  private requestAd(next: AdNext) {
    if (this.pendingAd || !this.active) return;
    this.pendingAd = next;
    this.started = false;
    this.events.emit("adBreakRequest");
  }

  /** Реклама закончилась: уходим туда, куда игрок собирался. */
  private initAds() {
    const { events } = this;

    events.on("adBreakContinue", () => {
      const next = this.pendingAd;
      this.pendingAd = undefined;
      if (!this.active || !next || next === "recycle") return;
      if (next === "menu") events.emit("requestMenuScreen");
      else events.emit("requestGameScreen", { gameId: next });
    });
  }

  /** Результат рекламы за заряды: награда — заряды в кошелёк; чужие запросы игнорируются. */
  private initMagicReward() {
    const { magicRewardCharges } = this.round.config;

    this.events.on("coreAdRewardedResult", ({ requestId, rewardId, rewardGranted }) => {
      if (requestId !== this.pendingMagicReward || rewardId !== "magic") return;
      this.pendingMagicReward = undefined;
      if (rewardGranted) this.charges.add(magicRewardCharges);
    });
  }

  /** Время идёт раз в секунду, только после первого хода и до победы. */
  private initTimer() {
    const { scene } = this.props;
    const { core } = this.round;

    const timer = scene.time.addEvent({
      delay: 1000,
      loop: true,
      callback: () => {
        const { won, historyLength } = core.state.getState();
        if (!this.started || won) return;
        this.score.updateData({ seconds: ++this.seconds });
        this.hud.update(this.seconds, historyLength, this.baseScore);
      }
    });
    this.unSubs.addUnSub(() => timer.remove());
  }

  /** Кнопки панели шлют команды, исполняет их экран. */
  private initHudCommands() {
    const { gameId } = this.props;
    const { core } = this.round;
    const { sceneEvents, dialogs } = this;
    const { EngineStep } = cardEngineV1;

    sceneEvents.on("hudHome", () => dialogs.open("home", () => this.requestAd("menu")));
    sceneEvents.on("hudSettings", () => dialogs.open("settings"));
    sceneEvents.on("hudHelp", () => this.openHelp());
    sceneEvents.on("hudNewGame", () => dialogs.open("restart", () => this.requestAd(gameId)));
    sceneEvents.on("hudUndo", () => {
      void core.undo();
    });
    /** Есть заряд — волшебный ход; нет — предложение рекламы. Заряд тратится, только когда ход точно будет. */
    sceneEvents.on("hudMagic", () => {
      const { magic, step } = core.state.getState();
      if (magic == null || step !== EngineStep.IDLE) return;
      if (this.charges.spend()) {
        void core.magic();
      } else this.offerMagicAd();
    });
    sceneEvents.on("hudHint", () => void core.showHint());
  }

  /** Карты запаса ловит партия; пустое место колоды — клик игры: оборот сброса Косынки. */
  private initStockButton() {
    const { stock, core } = this.round;
    if (!stock) return;

    makeButton({
      obj: stock,
      onClick: () => {
        this.started = true;
        void core.dealStock?.();
      }
    });
  }

  /**
   * Звук — по фактам партии: одно событие — один звук.
   * Стартовая раздача Паука идёт пачками — свой шаг группы; добор колоды и другие игры — шаг карты.
   */
  private initDealSounds() {
    const { gameId } = this.props;
    const { coreEvents, events } = this;
    let startDeal = false;

    coreEvents.on("onSolitaireDealStart", () => {
      startDeal = true;
    });
    coreEvents.on("onSolitaireDealFinished", () => {
      startDeal = false;
    });
    coreEvents.on("onSolitaireDealStep", () => {
      if (gameId === "spider" && startDeal) events.emit("spiderDealGroupStep");
      else events.emit("cardDeal", { gameId });
    });
  }

  /** Ходы игрока и отказы партии: счёт ходов, старт времени, звуки. */
  private initMoves() {
    const { coreEvents, events } = this;

    coreEvents.on("onSolitaireMoveStart", ({ type, cards, toStack }) => {
      /** возврат сброса в колоду — свой звук и реклама **/
      this.onMove(toStack?.type === "stock" ? "recycle" : type, cards);
    });
    coreEvents.on("onCardDrop", ({ card, toStack, success }) => {
      if (success) this.onMove("drop", [card]);
    });
    /** карта легла на базу: звук и конфетти только на первой и последней карте базы **/
    coreEvents.on("onSolitaireMoveSuccess", ({ type, toStack }) => {
      if (toStack?.type !== "base") return;

      this.checkBaseCelebrations(type, toStack);
    });
    coreEvents.on("onSolitaireMoveReject", () => {
      this.started = true;
      events.emit("cardReject");
    });
    coreEvents.on("onSolitaireError", ({ error, data }) =>
      console.error("Solitaire:", error, data)
    );
  }

  /** Звук и конфетти на базе: первая и последняя карта у игрока, у Паука — собранная масть. */
  private checkBaseCelebrations(type: string, toStack: cardEngineV1.IDragDropCardStack) {
    const { gameId } = this.props;
    /** База собирает всю масть: 13 карт от первой до последней. */
    const baseSize = 13;

    /** Паук собирает масть целиком автоходом — один праздник, когда каскад доиграл. */
    if (type === "auto") {
      if (gameId === "spider" && toStack.length === baseSize) {
        this.celebrateBase(toStack.cardPlace);
      }
      return;
    }

    if (toStack.length === 1 || toStack.length === baseSize) {
      this.celebrateBase(toStack.cardPlace);
    }
  }

  /** Звук кассы и конфетти — одна пара: один повод, один момент, одно место. */
  private celebrateBase(place: ICardPlace) {
    this.events.emit("cardToBase");
    this.flashBase(place);

    /** 0.002 — около 4 px на 1920: дёргает, но интерфейс не разваливается. */
    this.props.scene.cameras.main.shake(140, 0.002);
  }

  /** Ход игрока: клик, колода, магия — Start партии; drop — касание движка. Автоход звучит, но не считается. */
  private onMove(type: string, cards: readonly unknown[]) {
    const { gameId } = this.props;

    this.events.emit("onMoveStarted", { gameId, type, cards });
    if (type === "auto") return;
    this.started = true;
    if (type === "recycle") this.recycleAdPending = true;
    this.score.updateData({ moves: ++this.moves });
  }

  /** Вспышка конфетти в месте базы: готовый узор библиотеки, эмиттер убирает себя сам. */
  private flashBase(place: ICardPlace) {
    const { scene } = this.props;

    Explosions.confetti({ scene, x: place.x, y: place.y, ...baseConfettiStyle }).setDepth(1000);
  }

  /** Кнопки, очки и «Собрать» — по готовому состоянию партии после каждого действия. */
  private initCoreState() {
    const { isRewardedAvailable } = this.props;
    const { core, cards } = this.round;
    const { hud, charges } = this;
    const { EngineStep } = cardEngineV1;

    this.unSubs.addUnSub(
      core.state.on((state) => {
        // Перетаскивание — тоже первый ход: таймер стартует сразу, не дожидаясь дропа.
        if (state.step === EngineStep.DRAGGING) {
          this.started = true;
        }
        // enabled — только смысловые условия: транзиентный step не мигает кнопками.
        // Повторный запуск во время анимации гасит партия: её действия работают только в IDLE.
        hud.undo.setData("enabled", state.historyLength > 0);
        hud.hint.setData("enabled", state.hint != null);
        this.syncCollect(state);
        // Тинт палочки — по готовому ходу магии; без зарядов кнопка жива, только если можно получить их за рекламу.
        hud.magic?.setData(
          "enabled",
          state.magic != null && (charges.count > 0 || isRewardedAvailable())
        );
        this.setMagicBadge(charges.count);
        // Основа — по готовому раскладу после хода или отмены.
        if (state.step === EngineStep.IDLE) this.score.updateData({ cards });
        hud.update(this.seconds, state.historyLength, this.baseScore);
      })
    );
  }

  /** Отмена — тоже ход для бонуса, и время с неё тоже идёт. */
  private initUndoCount() {
    const { core } = this.round;

    this.unSubs.addUnSub(
      core.state.on(({ action }) => {
        if (action !== "undo") return;
        this.started = true;
        this.score.updateData({ moves: ++this.moves });
      }, "action")
    );
  }

  /** Победа: сначала танец карт с баз (если включён), по его концу или клику — окно победы. */
  private initWin() {
    const { scene, gameId, isWinAnimationAllowed } = this.props;
    const { core } = this.round;

    this.unSubs.addUnSub(
      core.state.on(({ won }) => {
        if (!won) return;
        const result = this.score.getSessionScore();
        this.events.emit("solitaireResult", { gameId, score: result.total });
        const openWin = () => {
          this.dialogs.open(
            "win",
            () => this.requestAd(gameId),
            () => this.requestAd("menu"),
            result
          );
        };
        if (!isWinAnimationAllowed()) return openWin();
        this.unSubs.addUnSub(
          new WinDance({ scene, stacks: core.getStacks("base"), onDone: openWin })
        );
      }, "won")
    );
  }

  /** Тупик сообщаем сам, только когда он появился: перекладывания не открывают диалог после каждого хода. */
  private initDeadEnd() {
    const { gameId } = this.props;
    const { core } = this.round;
    const { EngineStep } = cardEngineV1;
    let lastDeadEnd: DialogKind | undefined;

    this.unSubs.addUnSub(
      core.state.on((state) => {
        if (state.step !== EngineStep.IDLE || state.won) return;
        const kind = state.deadEnd;
        if (kind && kind !== lastDeadEnd) {
          this.events.emit("solitaireResult", {
            gameId,
            score: this.score.getSessionScore().total
          });
          this.openDeadEnd(kind);
        }
        lastDeadEnd = kind;
      })
    );
  }

  /** Тупик: показываем очки; результат фиксируется при обнаружении, не при повторном открытии окна. */
  private openDeadEnd(kind: DialogKind) {
    const { gameId } = this.props;

    if (!this.round.config.showDeadEndDialog) return;
    this.dialogs.open(kind, () => this.requestAd(gameId), undefined, this.score.getSessionScore());
  }

  /** Реклама после оборота колоды: только после завершённого оборота; диалог тупика важнее рекламной паузы. */
  private initRecycleAd() {
    const { scene } = this.props;
    const { core } = this.round;
    const { dialogs } = this;
    const { EngineStep } = cardEngineV1;

    this.unSubs.addUnSub(
      core.state.on((state) => {
        if (!this.recycleAdPending || state.step !== EngineStep.IDLE) return;
        this.recycleAdPending = false;
        if (dialogs.isOpen) return;
        scene.time.delayedCall(0, () => {
          if (!dialogs.isOpen && core.state.getState().step === EngineStep.IDLE)
            this.requestAd("recycle");
        });
      })
    );
  }

  /** Бейдж — под три цифры: больше 999 не показываем. */
  private setMagicBadge(count: number) {
    const { magic } = this.hud;
    if (magic) setValueData(magic, Math.min(count, 999));
  }

  /** Правила текущей игры: текст по ключу help_{игра}_text. */
  private openHelp() {
    const { events, t, gameId } = this.props;

    this.dialogs.show(
      (scene, close) =>
        new HelpView({
          scene,
          events,
          close,
          title: t("help_title").replace("{game}", t(gameId)),
          text: t(`help_${gameId}_text`)
        })
    );
  }

  /** Реклама за заряды: диалог явно говорит, что будет реклама и сколько зарядов; время на рекламе стоит. */
  private offerMagicAd() {
    const { isRewardedAvailable } = this.props;
    const { magicRewardCharges } = this.round.config;
    if (!isRewardedAvailable()) return;

    this.dialogs.open(
      "magicAd",
      () => {
        this.started = false;
        this.pendingMagicReward = `magic-${++this.magicAdRequests}`;
        this.events.emit("coreAdRewardedRequest", {
          requestId: this.pendingMagicReward,
          rewardId: "magic"
        });
      },
      undefined,
      undefined,
      magicRewardCharges
    );
  }

  /** Кнопка «Собрать»: показывается на решённой партии и исчезает, когда партия решённой быть перестала. */
  private syncCollect({ autoCollect, step }: ISolitaireCoreState) {
    const idle = step === cardEngineV1.EngineStep.IDLE;

    if (autoCollect && idle && !this.collect && !this.collecting) this.createCollect();
    if (!autoCollect) this.removeCollect();
    this.collect?.setData("enabled", idle);
  }

  /** Создаёт кнопку «Собрать»: место зависит от игры и задаётся здесь, анимация — только после расстановки. */
  private createCollect() {
    const { scene, events, t, gameId } = this.props;
    const bases = arrayAlign.alignObject(
      this.round.core.getStacks("base").map((stack) => stack.cardPlace)
    );

    const button = makeAutoCollectButton({
      scene,
      events,
      text: t("autoCollect"),
      onClick: () => this.runCollect()
    });
    layoutAutoCollectButton({ button, bases, gameId });
    startAutoCollectCta(button);
    this.collect = button;
  }

  /** Клик по кнопке: она уже уничтожена, запускаем сбор; пока он идёт, новая кнопка не появляется. */
  private runCollect() {
    this.collect = undefined;
    this.collecting = true;
    void this.round.core.autoCollect().finally(() => {
      this.collecting = false;
    });
  }

  /** Убирает кнопку «Собрать», если она есть. */
  private removeCollect() {
    this.collect?.destroy();
    this.collect = undefined;
  }
}
