import { CursorFeature, UnSubManager } from "@kvisaz/phaser-common";
import { cursorConfig } from "../configs/config.cursors";
import { soundConfig, soundSettings } from "../configs/config.sound";
import { SCENES } from "../scenes";
import { services } from "../services";
import { GameAdsService } from "../services/ads/GameAdsService";
import { GameSoundService } from "../services/sound/GameSoundService";

/** Сервисы работают до перезагрузки страницы и не перезапускаются вместе с экранами. */
export class ServicesScene extends Phaser.Scene {
  private readonly unSubs = new UnSubManager();

  /** Регистрирует постоянную сцену под общим ключом. */
  constructor() {
    super(SCENES.services);
  }

  /** Подключает постоянных обработчиков до запуска первого экрана. */
  create(): void {
    const { adsService, gameEvents, playerDataService, leaderboardService } = services;
    const scene = this;
    const events = gameEvents;
    this.unSubs.addUnSub(leaderboardService);

    /** Рекламные запросы и звук обслуживаются независимо от текущего экрана. */
    this.unSubs.addUnSub(new GameAdsService({ scene, events, ads: adsService }));
    this.unSubs.addUnSub(
      new GameSoundService({
        scene,
        events,
        playerData: playerDataService,
        settings: soundSettings,
        config: soundConfig,
      }),
    );

    /** Курсор работает на протяжении всей игры. */
    this.unSubs.addUnSub(new CursorFeature({ scene, config: cursorConfig }));
  }

  /** Явная очистка постоянных обработчиков. В обычной игре сцена не выключается. */
  destroy(): void {
    this.unSubs.destroy();
  }
}
