import {
  AdsService,
  GameLocale,
  LeaderboardService as LeaderboardsApi,
  SaveService,
  YandexDataService,
  YandexSdkWrapperV2,
} from "@kvisaz/phaser-common";
import packageInfo from "../../package.json";
import { localeConfig } from "../configs/config.locale";
import { buildConstants } from "../constants.build";
import { PlayerDataService } from "./playerData/PlayerDataService";
import { leaderboardConfig } from "../configs/config.leaderboard";
import { LeaderBoardService } from "./leaderboards/LeaderBoardService";

/** Общие сервисы игры, доступные через единственный экземпляр модуля. */
export class Services {
  public readonly gameEvents = new Phaser.Events.EventEmitter();
  public readonly yandexSdkWrapperV2 = new YandexSdkWrapperV2();
  public readonly locale = new GameLocale(localeConfig);
  public readonly adsService = new AdsService({
    isMockAd: !buildConstants.publishBuild,
    adCooldownMs: 100_000,
  });
  public readonly playerDataService = new PlayerDataService();

  public readonly saveService = new SaveService({
    appId: packageInfo.name,
    dataKey: `${packageInfo.name}-state`,
  });
  public readonly leaderboardsApi = new LeaderboardsApi({
    appId: packageInfo.name,
    config: leaderboardConfig,
    locale: this.locale,
  });
  public readonly leaderboardService = new LeaderBoardService({
    events: this.gameEvents,
    leaderboards: this.leaderboardsApi,
    playerDataService: this.playerDataService,
  });

  /**
   *  Вызывается один раз в BootScene. До завершения подготовки игровые сцены не запускаются.
   *  Готовит API, хранилище и данные игрока до запуска любых экранов.
   * */
  async prepareGameServices(): Promise<void> {
    const { yandexSdkWrapperV2, adsService, saveService, locale } = this;
    await yandexSdkWrapperV2.init();

    const sdk = yandexSdkWrapperV2.getSDK();
    const player = yandexSdkWrapperV2.getPlayer();
    adsService.preload(sdk);
    await saveService.preload(player ? new YandexDataService(player) : undefined);
    locale.resolve(yandexSdkWrapperV2.getLanguage());

    this.playerDataService.init(saveService);
    if (!this.playerDataService.getData().firstStartAt)
      void this.playerDataService.patch(() => ({ firstStartAt: Date.now() })).flush();
    this.leaderboardService.preload(yandexSdkWrapperV2);
  }
}
