import { makeAlign, makeView } from "@kvisaz/phaser-common";
import { getImageAsset } from "../../../../assets";
import { iconButton, textButton } from "../../buttons";
import { DialogShell } from "./components/DialogShell";
import { uiTextStyle } from "../../style";
import { toggle } from "../../toggle";
import { dialogViewConfig } from "../config";
import { ScoreBlock } from "./ScoreBlock/ScoreBlock";
import { DialogKind, IDialogScore } from "../types";

interface IDialogViewProps {
  scene: Phaser.Scene;
  events: Phaser.Events.EventEmitter;
  t(key: string): string;
  kind: DialogKind;
  close(): void;
  dismiss(): void;
  confirm?: () => void;
  score?: IDialogScore;
  reward?: number;
  settings: { isSoundOn: boolean; isMusicOn: boolean };
  onSettingsChange(settings: { isSoundOn: boolean; isMusicOn: boolean }): void;
  isWinAnimationAllowed: boolean;
  onWinAnimationAllowedChange(value: boolean): void;
}

/** Диалог Classic XL по его виду: кнопки и содержимое собираются здесь, рамку, шапку и кнопки ставит DialogShell. */
export function createDialogView(props: IDialogViewProps) {
  const { scene, events, t } = props;
  const { kind, close } = props;
  const illustrated = kind === "win" || kind === "noMoves" || kind === "uselessMoves";
  const buttons =
    kind === "settings"
      ? [textButton({ scene, events, text: t("done"), onClick: close })]
      : [
          textButton({
            scene,
            events,
            text: t(kind === "win" ? "back_to_menu" : "back_to_game"),
            onClick: close,
            variant: "secondary",
            width: 500,
          }),
          textButton({
            scene,
            events,
            text: t(
              kind === "home" ? "back_to_menu" : kind === "magicAd" ? "watch_ad" : "new_game",
            ),
            onClick: () => props.confirm?.(),
            variant: "primary",
            width: 572,
          }),
        ];
  /** Строки настроек: звук и музыка уходят в ядро, анимации победы — в сохранение игры. */
  const soundRow = (key: "isSoundOn" | "isMusicOn", label: string) => ({
    label,
    isOn: props.settings[key],
    onChange: (value: boolean) => {
      props.settings[key] = value;
      props.onSettingsChange({ ...props.settings });
    },
  });
  const rows = (
    kind === "settings"
      ? [
          soundRow("isSoundOn", "sound"),
          soundRow("isMusicOn", "music"),
          {
            label: "win_animations",
            isOn: props.isWinAnimationAllowed,
            onChange: props.onWinAnimationAllowedChange,
          },
        ]
      : []
  ).map(({ label, isOn, onChange }) => ({
    label,
    button: toggle({ scene, events, t }, isOn, onChange),
  }));
  // Блок очков создаётся до тела окна: вложенный makeView запрещён.
  const scoreBlock =
    props.score && illustrated ? createScoreBlock(scene, t, props.score) : undefined;

  // У победы нет возврата в игру: только «Новая игра» и «В меню», без крестика.
  const closeButton =
    kind === "win"
      ? undefined
      : iconButton({ scene, events, name: "close", onClick: props.dismiss });
  const shell = new DialogShell({ scene, title: t(`dialog_${kind}`), closeButton, buttons });
  const { bg } = shell;

  const body = makeView(scene, (b) => {
    const items: Phaser.GameObjects.GameObject[] = [];
    makeAlign((a) => {
      if (kind === "settings") {
        rows.forEach(({ label, button }, i) => {
          const text = b.text({ text: t(label), style: uiTextStyle(48) });
          a.anchor(bg)
            .leftIn(text, 80)
            .topIn(text, 187 + i * 125);
          a.rightIn(button, -80).topIn(button, 165 + i * 125);
          items.push(text, button);
        });
        return;
      }
      const style = { ...uiTextStyle(40), wordWrap: { width: illustrated ? 760 : 1080 } };
      const message = b.text({
        text: t(`dialog_${kind}_message`).replace("{n}", String(props.reward ?? "")),
        style,
      });
      a.anchor(bg)
        .leftIn(message, 72)
        .topIn(message, illustrated ? 184 : 240);
      items.push(message);
      if (!illustrated) return;

      // Итог сеанса: очки между первой строкой и пояснением над кнопками.
      if (scoreBlock) {
        a.anchor(message).leftIn(scoreBlock).bottomTo(scoreBlock, dialogViewConfig.blockGap);
        items.push(scoreBlock);
      }

      // Пояснение — над кнопками, под картинкой на всю ширину.
      const { footerFontSize, footerWrapWidth, footerAlpha, footerGap } = dialogViewConfig;
      const footer = b
        .text({
          text: t(`dialog_${kind}_footer`),
          style: { ...style, fontSize: footerFontSize, wordWrap: { width: footerWrapWidth } },
        })
        .setAlpha(footerAlpha);
      a.anchor(buttons[0]).leftIn(footer).topTo(footer, -footerGap);
      const art = b
        .img(getImageAsset(kind === "win" ? "dialogWin" : "dialogNoMoves"))
        .setDisplaySize(300, 300);
      a.anchor(bg).rightIn(art, -64).topIn(art, 195);
      items.push(footer, art);
    });
    return b.con(items);
  });
  shell.add(body);
  return shell;
}

/** Место в рейтинге намеренно не показываем: передача данных рейтинга в диалог усложняла код. */
function createScoreBlock(scene: Phaser.Scene, t: (key: string) => string, score: IDialogScore) {
  return new ScoreBlock({
    scene,
    bases: score.bases,
    time: score.time,
    moves: score.moves,
    total: score.total,
    texts: {
      total: t("score_total"),
      bases: t("score_bases"),
      time: t("score_time"),
      moves: t("score_moves"),
      place: t("score_place"),
    },
    hasPlace: false,
  });
}
