import { gamesConfig, solitaireIds } from "./config.games";
import { rivalNames } from "./config.rivalNames";

const { scoreMax } = gamesConfig;

/** Очки соперников без Яндекса: от 40% до максимума доски. */
function rivalScores(max: number) {
  return { min: Math.round(max * 0.4), max };
}

/** Доски рейтинга: имена — как в консоли Яндекса; all — сумма рекордов пяти игр в одной шкале. */
export const leaderboardConfig = {
  /** SDK принимает не больше одной записи в секунду, включая общую доску. */
  writeIntervalMs: 1100,
  top: 10,
  around: 1,
  virtual: {
    rivals: 120,
    scores: {
      ...Object.fromEntries(solitaireIds.map((id) => [id, rivalScores(scoreMax)])),
      all: rivalScores(scoreMax * solitaireIds.length),
    },
    names: rivalNames,
  },
};
