import { makeAlign, makeView } from "@kvisaz/phaser-common";
import type { DialogButton } from "../../dialog/types";
import { uiTextStyle } from "../../style";

interface ILeaderboardFailedProps {
  scene: Phaser.Scene;
  text: string;
  /** нет кнопки — нет и повтора: флаг управляется снаружи */
  retryButton?: DialogButton;
}

/** Ошибка вместо таблицы: надпись и, если передана кнопка, она под надписью. */
export class LeaderboardFailed extends Phaser.GameObjects.Container {
  constructor(private props: ILeaderboardFailedProps) {
    super(props.scene, 0, 0);
    const { scene, text, retryButton } = this.props;
    const message = makeView(scene, (b) => b.text({ text, style: uiTextStyle(34) }));
    this.add(message);
    if (!retryButton) return;

    makeAlign((a) => a.anchor(message).centerX(retryButton).bottomTo(retryButton, 40));
    this.add(retryButton);
  }
}
