import {
  SafeEventsAdapter,
  SoundFeature,
  UnSubManager,
  type IGameCoreSoundConfig,
} from "@kvisaz/phaser-common";
import type { PlayerDataService } from "../playerData/PlayerDataService";
import type { ISoundState } from "../playerData/types";
import type { IGameSoundEvents } from "./events";

interface IGameSoundServiceProps {
  scene: Phaser.Scene;
  events: Phaser.Events.EventEmitter;
  playerData: PlayerDataService;
  settings: ISoundState;
  config: IGameCoreSoundConfig<IGameSoundEvents>;
}

/** Один владелец музыки, настроек и временного mute на всё приложение. */
export class GameSoundService {
  private readonly unSubs = new UnSubManager();

  /** Восстанавливает настройки до первого звука; смена экрана не пересоздаёт фичу. */
  constructor(private readonly props: IGameSoundServiceProps) {
    const { playerData, settings, scene, config } = props;

    /** Собираем подписки сохранения настроек и звуковой фичи в одном адаптере. */
    const events = new SafeEventsAdapter<IGameSoundEvents>(props.events);
    this.unSubs.addUnSub(() => events.unSubscribeAll());

    Object.assign(settings, playerData.getData().sound);
    events.on("coreSoundSettingsChanged", (next) => {
      Object.assign(settings, next);
      const saved = playerData.getData().sound;
      if (saved?.isSoundOn !== next.isSoundOn || saved?.isMusicOn !== next.isMusicOn) {
        void playerData.patch(() => ({ sound: { ...next } })).flush();
      }
    });
    this.unSubs.addUnSub(
      new SoundFeature<IGameSoundEvents>({
        scene,
        events,
        config: { ...config, initialSettings: { ...settings } },
      }),
    );
  }

  /** Останавливает музыку и отписывает сервис только при завершении приложения. */
  destroy(): void {
    this.unSubs.destroy();
  }
}
