import { SafeEventsAdapter, UnSubManager, type SaveResult } from "@kvisaz/phaser-common";
import type { IDemoEvents, IDemoRewardResult } from "./events";
import { restartScene } from "../../../scenes";

interface IDemoActionsProps {
  scene: Phaser.Scene;
  events: Phaser.Events.EventEmitter;
  getCounter(): number;
  saveCounter(value: number): Promise<SaveResult>;
  getLanguage(): string;
  setLanguage(value: string): void;
  refresh(): void;
}

/**
 * Проверяет события и сервисы стартера отдельно от вёрстки стенда.
 * Отступление от `code-rules.md`: держит собственный `soundOn`, не синхронизируя его
 * с общим `soundSettings` — осознанное послабление для демонстрационного стенда.
 */
export class DemoActions {
  private readonly unSubs = new UnSubManager();
  private readonly events: SafeEventsAdapter<IDemoEvents>;
  counter: number;
  seconds = 0;
  eventCount = 0;
  muted = false;
  soundOn = true;
  status = "status_ready";
  private active = true;
  private statusVersion = 0;
  private pendingReward?: string;
  private static requestNumber = 0;

  /** Восстанавливает счётчик, подключает события и регистрирует очистку таймера. */
  constructor(private readonly props: IDemoActionsProps) {
    const { scene, getCounter, refresh } = props;

    /** Все обработчики стенда снимаются одним вызовом при его закрытии. */
    const events = (this.events = new SafeEventsAdapter<IDemoEvents>(props.events));
    this.unSubs.addUnSub(() => events.unSubscribeAll());

    this.counter = getCounter();
    events.on("demoIncrement", () => {
      this.eventCount++;
      void this.increment();
    });
    events.on("demoFullscreenContinue", () => {
      this.setStatus("status_fullscreen_done");
    });
    events.on("coreAdRewardedResult", (result) => this.onReward(result));
    const timer = scene.time.addEvent({
      delay: 1000,
      loop: true,
      callback: () => {
        this.seconds++;
        refresh();
      },
    });
    this.unSubs.addUnSub(() => timer.remove(false));
  }

  /** Обновляет статус; версия защищает его от запоздалого результата сохранения. */
  private setStatus(key: string): number {
    this.status = key;
    this.props.refresh();
    return ++this.statusVersion;
  }

  /** Сохраняет через ядро и сообщает успех только после подтверждённой записи. */
  private async increment(success = "status_saved"): Promise<void> {
    const next = this.counter + 1;
    if (!Number.isSafeInteger(next)) {
      this.setStatus("status_counter_limit");
      return;
    }
    this.counter = next;
    const version = this.setStatus("status_saving");
    try {
      // Счётчик дописывается к данным игрока, а не затирает их.
      const result = await this.props.saveCounter(next);
      if (!this.active || version !== this.statusVersion) return;
      this.setStatus(result.errorMessage ? "status_save_failed" : success);
    } catch {
      if (this.active && version === this.statusVersion) this.setStatus("status_save_failed");
    }
  }

  /** Запускает декларативную цепочку fullscreen → continue, включая недоступную рекламу. */
  fullscreen(): void {
    this.setStatus("status_fullscreen_requested");
    this.events.emit("demoFullscreenRequest");
  }

  /** Не допускает двух ожидающих rewarded-запросов с одного стенда. */
  rewarded(): void {
    if (this.pendingReward) return;
    this.pendingReward = `solitaires-demo-${++DemoActions.requestNumber}`;
    this.setStatus("status_reward_requested");
    this.events.emit("coreAdRewardedRequest", {
      requestId: this.pendingReward,
      rewardId: "demo-counter",
    });
  }

  /** Начисляет награду один раз и только для подтверждённого собственного запроса. */
  private onReward(result: IDemoRewardResult): void {
    if (result.requestId !== this.pendingReward || result.rewardId !== "demo-counter") return;
    this.pendingReward = undefined;
    if (result.rewardGranted) void this.increment("status_reward_granted");
    else this.setStatus("status_reward_failed");
  }

  /** Проверяет независимый временный mute, который не должна снимать реклама. */
  toggleMute(): void {
    this.muted = !this.muted;
    this.events.emit("coreSoundMuteRequest", {
      owner: "solitaires-demo",
      muted: this.muted,
    });
    this.setStatus(this.muted ? "status_muted" : "status_unmuted");
  }

  /** Проверяет постоянные настройки эффектов отдельно от временного mute. */
  toggleSound(): void {
    this.soundOn = !this.soundOn;
    this.events.emit("coreSoundSettingsChanged", {
      isMusicOn: false,
      isSoundOn: this.soundOn,
    });
    this.setStatus(this.soundOn ? "status_sound_on" : "status_sound_off");
  }

  /** Переключает локаль и пересоздаёт контент; URL сохраняет выбор при перезагрузке страницы. */
  toggleLanguage(): void {
    const { scene, getLanguage, setLanguage } = this.props;
    setLanguage(getLanguage() === "ru" ? "en" : "ru");
    const url = new URL(window.location.href);
    url.searchParams.set("lang", getLanguage());
    window.history.replaceState({}, "", url);

    restartScene(scene);
  }

  /** Запрещает асинхронным сохранениям обновлять уже уничтоженное представление. */
  destroy(): void {
    this.active = false;
    this.pendingReward = undefined;
    this.unSubs.destroy();
    // Владелец звука постоянный: уход со стенда снимает только его временный mute.
    this.events.emit("coreSoundMuteRequest", { owner: "solitaires-demo", muted: false });
  }
}
